            {
                this.ReportMissingRequired(context, "tyhpClassOperatorOverloadDecl.tyhpClassOperatorOverload");
                return TyhpOperatorOverloadAst.CreateError(context, languageMode);
            }

            TokenValueAst op;
            if (opCtx.Op != null)
