            [NotNull] TyhpParser.FunctionNameGrammarAddonContext context)
            => context.GenericParameters != null
                ? this.VisitTyhpGenericParameterDeclarations(context.GenericParameters)
                : null;


        /// <summary>
        /// functionParametersGrammarAddon
        ///     : IsExtension=T_EXTENDS? {this.isLanguageMode("tyhp")}?
        ///     ;
        ///
        /// Returns a TokenValueAst for the extends keyword if present,
        /// indicating this function's first parameter is an extension receiver.
        /// Attached as the "parameters" grammar addon on PhpFunctionDeclAst.
        /// </summary>
        public override IBase2Ast? VisitFunctionParametersGrammarAddon(
            [NotNull] TyhpParser.FunctionParametersGrammarAddonContext context)
            => context.IsExtension != null
                ? this.GetTokenValueAst(context, context.IsExtension)
                : null;


        public override ITypeExpression VisitGroupedType(
            [NotNull] TyhpParser.GroupedTypeContext context)
        {
            if (context.TypeExpr != null)
            {
                return this.VisitTypeExpr(context.TypeExpr);
            }

            this.ReportMissingRequired(context, "groupedType.TypeExpr");
            return PhpTypeExpressionAst.CreateError(context, GetCurrentLanguageMode(context));
        }


        public override TyhpExtensionDeclAst VisitTyhpInnerExtensionDecl([NotNull] TyhpParser.TyhpInnerExtensionDeclContext context)
        {
            if (context.Statement == null)
            {
                this.ReportMissingRequired(context, "tyhpInnerExtensionDecl.Statement");
                return TyhpExtensionDeclAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var decl = this.VisitTyhpExtensionDeclarationStatement(context.Statement);
            if (context.Attributes != null)
            {
                decl.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return decl;
        }


        public override TyhpTypeAliasAst VisitTyhpInnerTypeAliasDecl([NotNull] TyhpParser.TyhpInnerTypeAliasDeclContext context)
        {
            if (context.Statement == null)
            {
                this.ReportMissingRequired(context, "tyhpInnerTypeAliasDecl.Statement");
                return TyhpTypeAliasAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var alias = this.VisitTyhpTypeAlias(context.Statement)
                .WithAttributes(context.Attributes != null ? this.VisitAttributes(context.Attributes) : null);
            if (context.IsInternal != null)
            {
                alias.AddGrammarAddon("isInternal", TokenValueAst.Create(context.IsInternal, context));
            }

            return alias;
        }


        public override IStatement VisitTyhpInnerFallbackDecl([NotNull] TyhpParser.TyhpInnerFallbackDeclContext context)
        {
            var statement = this.VisitAttributedStatement(context.Statement);
            if (context.Attributes != null)
            {
                statement.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            statement.MarkFallback(context.IsFallback, context);
            return statement;
        }


        public override IStatement VisitInnerStatementGrammarAddon([NotNull] TyhpParser.InnerStatementGrammarAddonContext context)
        {
            return context switch
            {
                TyhpParser.TyhpInnerExtensionDeclContext c => this.VisitTyhpInnerExtensionDecl(c),
                TyhpParser.TyhpInnerTypeAliasDeclContext c => this.VisitTyhpInnerTypeAliasDecl(c),
                TyhpParser.TyhpInnerFallbackDeclContext c => this.VisitTyhpInnerFallbackDecl(c),
                _ => base.VisitInnerStatementGrammarAddon(context),
            };
        }


        public override PhpModifierListAst? VisitInterfaceModifiersGrammarAddon([NotNull] TyhpParser.InterfaceModifiersGrammarAddonContext context)
            => this.VisitOptionalInternalModifierList(context, context.IsInternal);


        /// <summary>
        /// Visits the interface name grammar addon, returning generic type arguments
        /// if present in Tyhp mode.
        ///
        /// Grammar (TyhpParser):
        ///   interfaceNameGrammarAddon
        ///     : GenericArguments=tyhpGenericParameterDeclarations?
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override IBase2Ast? VisitInterfaceNameGrammarAddon([NotNull] TyhpParser.InterfaceNameGrammarAddonContext context)
            => context.GenericArguments != null
                ? this.VisitTyhpGenericParameterDeclarations(context.GenericArguments)
                : null;

        /// <summary>
        /// Override the internal functions grammar addon to dispatch to
        /// Tyhp compile-time construct handlers.
        ///
        /// Grammar (TyhpParser.g4):
        ///   internalFunctionsGrammarAddon
        ///       : T_TYHP_VARIABLE_EXISTS T_OPEN_ROUND_BRACE Expr=expr T_CLOSE_ROUND_BRACE
        ///           {this.isLanguageMode("tyhp")}?    #tyhpInternalFunctionVariableExists
        ///       | T_TYHP_TYPEOF T_OPEN_ROUND_BRACE TypeExpr=typeExpr T_CLOSE_ROUND_BRACE
        ///           {this.isLanguageMode("tyhp")}?    #tyhpInternalFunctionTypeof
        ///       | T_TYHP_TYPEOF BuiltinCast=(T_DOUBLE_CAST|…)
        ///           {this.isLanguageMode("tyhp")}?    #tyhpInternalFunctionTypeofBuiltinCast
        ///       | T_DEFAULT T_OPEN_ROUND_BRACE TypeExpr=typeExpr T_CLOSE_ROUND_BRACE
        ///           {this.isLanguageMode("tyhp")}?    #tyhpInternalFunctionDefault
        ///       | T_TYHP_NAMEOF T_OPEN_ROUND_BRACE Expr=expr T_CLOSE_ROUND_BRACE
        ///           {this.isLanguageMode("tyhp")}?    #tyhpInternalFunctionNameof
        ///       ;
        /// </summary>
        public override IStatement VisitInternalFunctionsGrammarAddon(
            [NotNull] TyhpParser.InternalFunctionsGrammarAddonContext context)
            => context switch
            {
                TyhpParser.TyhpInternalFunctionVariableExistsContext variableExistsCtx
                    => this.VisitTyhpInternalFunctionVariableExists(variableExistsCtx),
                TyhpParser.TyhpInternalFunctionTypeofContext typeofCtx
                    => this.VisitTyhpInternalFunctionTypeof(typeofCtx),
                TyhpParser.TyhpInternalFunctionTypeofBuiltinCastContext typeofCastCtx
                    => this.VisitTyhpInternalFunctionTypeofBuiltinCast(typeofCastCtx),
                TyhpParser.TyhpInternalFunctionDefaultContext defaultCtx
                    => this.VisitTyhpInternalFunctionDefault(defaultCtx),
                TyhpParser.TyhpInternalFunctionDefaultBuiltinCastContext defaultCastCtx
                    => this.VisitTyhpInternalFunctionDefaultBuiltinCast(defaultCastCtx),
                TyhpParser.TyhpInternalFunctionNameofContext nameofCtx
                    => this.VisitTyhpInternalFunctionNameof(nameofCtx),
                _ => base.VisitInternalFunctionsGrammarAddon(context),
            };


        /// <summary>
        /// Visit the variable_exists() compile-time construct.
        /// Checks whether a variable is defined.
        ///
        /// Grammar:
        ///   #tyhpInternalFunctionVariableExists
        ///       : T_TYHP_VARIABLE_EXISTS T_OPEN_ROUND_BRACE Expr=expr T_CLOSE_ROUND_BRACE
        /// </summary>
        public override TyhpVariableExistsAst VisitTyhpInternalFunctionVariableExists(
            [NotNull] TyhpParser.TyhpInternalFunctionVariableExistsContext context)
            => TyhpVariableExistsAst.Create(this.VisitExpr(context.Expr), context);


        /// <summary>
        /// Visit the typeof() compile-time construct.
        /// Materializes a runtime <c>\Tyhp\Type</c> value for the given type expression.
        ///
        /// Grammar:
        ///   #tyhpInternalFunctionTypeof
        ///       : T_TYHP_TYPEOF T_OPEN_ROUND_BRACE TypeExpr=typeExpr T_CLOSE_ROUND_BRACE
        /// </summary>
        public override TyhpTypeofAst VisitTyhpInternalFunctionTypeof(
            [NotNull] TyhpParser.TyhpInternalFunctionTypeofContext context)
            => TyhpTypeofAst.Create(this.VisitTypeExpr(context.TypeExpr), context);


        /// <summary>
        /// Visit typeof() when the type is written as a PHP cast token, e.g. <c>typeof(int)</c>.
        /// The PHP lexer tokenizes <c>(int)</c> as a single T_INT_CAST (parens included), so it
        /// cannot match the <c>typeExpr</c> form above. Maps the cast token to a PhpBuiltinTypeAst
        /// the same way default() does.
        ///
        /// Grammar:
        ///   #tyhpInternalFunctionTypeofBuiltinCast
        ///       : T_TYHP_TYPEOF BuiltinCast=(T_DOUBLE_CAST|T_OBJECT_CAST|T_INT_CAST|
        ///           T_STRING_CAST|T_BOOL_CAST|T_ARRAY_CAST|T_DECIMAL_CAST)
        /// </summary>
        public override TyhpTypeofAst VisitTyhpInternalFunctionTypeofBuiltinCast(
            [NotNull] TyhpParser.TyhpInternalFunctionTypeofBuiltinCastContext context)
        {
            var typeName = CastTokenTypeToTypeName(context.BuiltinCast.Type);
            var builtinType = PhpBuiltinTypeAst.Create(typeName, context);
            return TyhpTypeofAst.Create(builtinType, context);
        }


        /// <summary>
        /// Visit the default() compile-time construct.
        /// Returns the default value for a given type.
        ///
        /// Grammar:
        ///   #tyhpInternalFunctionDefault
        ///       : T_DEFAULT T_OPEN_ROUND_BRACE TypeExpr=typeExpr T_CLOSE_ROUND_BRACE
        /// </summary>
        public override TyhpDefaultAst VisitTyhpInternalFunctionDefault(
            [NotNull] TyhpParser.TyhpInternalFunctionDefaultContext context)
            => TyhpDefaultAst.Create(this.VisitTypeExpr(context.TypeExpr), context);


        /// <summary>
        /// Visit the default() compile-time construct when the type is written as a PHP cast token,
        /// e.g. <c>default(int)</c>. The PHP lexer tokenizes <c>(int)</c> as a single T_INT_CAST
        /// (parens included), so it cannot match the <c>typeExpr</c> form above. This alternative
        /// maps the cast token to the matching builtin type name and builds a TyhpDefaultAst whose
        /// TypeExpression is a PhpBuiltinTypeAst, so the emitter's BuildDefaultExpression produces
        /// the right zero value (0 / '' / false / [] / ...).
        ///
        /// Grammar:
        ///   #tyhpInternalFunctionDefaultBuiltinCast
        ///       : T_DEFAULT BuiltinCast=(T_DOUBLE_CAST|T_OBJECT_CAST|T_INT_CAST|
        ///           T_STRING_CAST|T_BOOL_CAST|T_ARRAY_CAST|T_DECIMAL_CAST)
        /// </summary>
        public override TyhpDefaultAst VisitTyhpInternalFunctionDefaultBuiltinCast(
            [NotNull] TyhpParser.TyhpInternalFunctionDefaultBuiltinCastContext context)
        {
            var typeName = CastTokenTypeToTypeName(context.BuiltinCast.Type);
            var builtinType = PhpBuiltinTypeAst.Create(typeName, context);
            return TyhpDefaultAst.Create(builtinType, context);
        }


        /// <summary>
        /// Visit the nameof() compile-time construct.
        /// Returns the string name of a symbol at compile time.
        ///
        /// Grammar:
        ///   #tyhpInternalFunctionNameof
        ///       : T_TYHP_NAMEOF T_OPEN_ROUND_BRACE Expr=expr T_CLOSE_ROUND_BRACE
        /// </summary>
        public override TyhpNameofAst VisitTyhpInternalFunctionNameof(
            [NotNull] TyhpParser.TyhpInternalFunctionNameofContext context)
            => TyhpNameofAst.Create(this.VisitExpr(context.Expr), context);


        /// <summary>
        /// legacyNamespaceNameGrammarAddon
        ///     : FullyQualifiedName=T_NAME_FULLY_QUALIFIED
        ///         GenericArguments=tyhpGenericTypeArguments
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override PhpNameAst VisitLegacyNamespaceNameGrammarAddon([NotNull] TyhpParser.LegacyNamespaceNameGrammarAddonContext context)
            => TyhpGenericIdentifierAst.Create(
                context.FullyQualifiedName,
                this.VisitTyhpGenericTypeArguments(context.GenericArguments),
                context
            );


        //#endregion Identifier and Name Grammar Addons

        //#region Modifier and Parameter Grammar Addons

        /// <summary>
        /// Visits the member modifier grammar addon for Tyhp <c>async</c> / <c>internal</c>.
        ///
        /// Grammar (TyhpParser):
        ///   memberModifierGrammarAddon
        ///     : TokenValue=T_TYHP_ASYNC {this.isLanguageMode("tyhp")}?
        ///     | TokenValue=T_TYHP_INTERNAL {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override TokenValueAst VisitMemberModifierGrammarAddon([NotNull] TyhpParser.MemberModifierGrammarAddonContext context)
            => this.GetTokenValueAst(context, context.TokenValue)
                ?? TokenValueAst.CreateError(context, GetCurrentLanguageMode(context));


        /// <summary>
        /// memberNameIdentifierGrammarAddon
        ///     : GenericArguments=tyhpGenericTypeArguments?
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override IBase2Ast? VisitMemberNameIdentifierGrammarAddon([NotNull] TyhpParser.MemberNameIdentifierGrammarAddonContext context)
            => context.GenericArguments != null
                ? this.VisitTyhpGenericTypeArguments(context.GenericArguments)
                : null;


        /// <summary>
        /// nameTokenValueGrammarAddon
        ///     : T_TYHP_VOID {this.isLanguageMode("tyhp")}?
        ///     | T_TYHP_PARENT {this.isLanguageMode("tyhp")}?
        ///     | T_TYHP_USING {this.isLanguageMode("tyhp")}?
        ///     | T_TYHP_ASYNC {this.isLanguageMode("tyhp")}?
        ///     | T_TYHP_OPERATOR {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override PhpNameAst VisitNameTokenValueGrammarAddon([NotNull] TyhpParser.NameTokenValueGrammarAddonContext context)
            => PhpNameAst.Create(context.Start, context);


        /// <summary>
        /// namespaceNameGrammarAddon
        ///     : (Name=T_STRING | QualifiedName=T_NAME_QUALIFIED)
        ///         GenericArguments=tyhpGenericTypeArguments
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override PhpNameAst VisitNamespaceNameGrammarAddon([NotNull] TyhpParser.NamespaceNameGrammarAddonContext context)
        {
            var genericArgs = this.VisitTyhpGenericTypeArguments(context.GenericArguments);
            var nameToken = context.Name ?? context.QualifiedName;
            if (nameToken == null)
            {
                return PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
            }
            return TyhpGenericIdentifierAst.Create(nameToken, genericArgs, context);
        }

        public override PhpNewAst VisitNewDereferenceableGrammarAddon([NotNull] TyhpParser.NewDereferenceableGrammarAddonContext context)
            => context switch
            {
                TyhpParser.TyhpNewAnonStructInstanceContext c => this.VisitTyhpNewAnonStructInstance(c),
                _ => base.VisitNewDereferenceableGrammarAddon(context),
            };


        /// <summary>
        /// Handles `new struct { ... }` expressions.
        ///
        /// Grammar:
        ///   newDereferenceableGrammarAddon
        ///     : {this.looksLikeAnonymousStruct()}?
        ///         T_NEW AnonStructDecl=tyhpAnonymousStruct {this.isLanguageMode("tyhp")}?
        ///         #tyhpNewAnonStructInstance
        ///     ;
        ///
        /// Follows the same pattern as anonymous classes: the struct declaration
        /// is registered as a top-level statement, and a PhpNewAst wrapping the
        /// struct's generated identifier is returned for use in expression context.
        /// </summary>
        public override PhpNewAst VisitTyhpNewAnonStructInstance([NotNull] TyhpParser.TyhpNewAnonStructInstanceContext context)
        {
            if (context.AnonStructDecl == null)
            {
                this.ReportMissingRequired(context, "tyhpNewAnonStructInstance.AnonStructDecl");
                return PhpNewAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var structDecl = this.VisitTyhpAnonymousStruct(context.AnonStructDecl);

            // Register the anonymous struct declaration in the current top statement list
            this.CurrentTopStatementList?.Add(structDecl);

            // Return a new-expression referencing the anonymous struct by its generated identifier
            return PhpNewAst.Create(
                PhpNameAst.Create(structDecl.Identifier, TyhpParser.T_STRING, context),
                null,
                context
            );
        }


        /// <summary>
        /// Preserve Tyhp <c>async</c> / <c>internal</c> on member modifier lists. PHP's
        /// <see cref="PhpModifier"/> has no Async value historically, so the base visitor
        /// mapped that token to <see cref="PhpModifier.None"/>. Attach grammar addons so the
        /// binder can set <c>IsAsync</c> / <c>IsInternal</c> / the matching <see cref="MemberModifier"/> flags.
        /// </summary>
        public override PhpModifierListAst VisitNonEmptyMemberModifiers([NotNull] TyhpParser.NonEmptyMemberModifiersContext context)
        {
            var result = base.VisitNonEmptyMemberModifiers(context);
            foreach (var item in context._Items)
            {
                var token = this.VisitMemberModifier(item);
                if (string.Equals(token.ValueString, "async", StringComparison.OrdinalIgnoreCase)
                    || token.ValueInt64 == TyhpParser.T_TYHP_ASYNC)
                {
                    result.AddGrammarAddon("isAsync", token);
                }
                else if (string.Equals(token.ValueString, "internal", StringComparison.OrdinalIgnoreCase)
                    || token.ValueInt64 == TyhpParser.T_TYHP_INTERNAL)
                {
                    result.AddGrammarAddon("isInternal", token);
                }
            }

            return result;
        }


        /// <summary>
        /// optionalTypeWithoutStatic
        ///     : TypeExpr=typeExprWithoutStatic? {!this.isLanguageMode("tyhp")}?
        ///     | TypeExpr=typeExprWithoutStatic {this.isLanguageMode("tyhp")}?
        ///     ;
        ///
        /// In Tyhp mode, the type expression is required (not optional).
        /// The base implementation already handles both cases correctly by
        /// checking if TypeExpr is present.
        /// </summary>
        public override ITypeExpression? VisitOptionalTypeWithoutStatic([NotNull] TyhpParser.OptionalTypeWithoutStaticContext context)
            => base.VisitOptionalTypeWithoutStatic(context);


        /// <summary>
        /// Visits the parameter type expression grammar addon.
        /// In Tyhp mode, parameter types are required (typeExprWithoutStatic).
        /// In PHP mode, parameter types are optional (optionalTypeWithoutStatic).
        ///
        /// Grammar (TyhpParser):
        ///   parameterTypeExpressionGrammarAddon
        ///     : {this.isLanguageMode("tyhp")}? typeExprWithoutStatic
        ///     | {!this.isLanguageMode("tyhp")}? optionalTypeWithoutStatic
        ///     ;
        ///
        /// The base PhpParserAstVisitor already handles both alternatives by
        /// checking which sub-rule is present, so we delegate to it.
        /// </summary>
        public override ITypeExpression? VisitParameterTypeExpressionGrammarAddon([NotNull] TyhpParser.ParameterTypeExpressionGrammarAddonContext context)
            => base.VisitParameterTypeExpressionGrammarAddon(context);


        /// <summary>
        /// <c>async { ... }</c> — a Promise-valued block, not a callable.
        /// </summary>
        public override IExpression VisitPhpExprPrecBaseGrammarAddon(
            [NotNull] TyhpParser.PhpExprPrecBaseGrammarAddonContext context)
        {
            var body = context.StatementList != null
                ? this.VisitInnerStatementList(context.StatementList)
                : PhpStatementBlockAst.CreateError(context, GetCurrentLanguageMode(context));
            return TyhpAsyncBlockAst.Create(body, context, GetCurrentLanguageMode(context));
        }


        /// <summary>
        /// Overrides the grammar addon for unary postfix operators.
        /// Tyhp does not currently add new postfix operators.
        /// </summary>
        public override TokenValueAst? VisitPhpExprUnaryPostOpsGrammarAddon([NotNull] TyhpParser.PhpExprUnaryPostOpsGrammarAddonContext context)
            => this.GetTokenValueAst(context, context.TokenValue);

        /// <summary>
        /// Overrides the grammar addon for unary prefix operators.
        /// Tyhp adds: T_DECIMAL_CAST, T_TYHP_AWAIT
        /// </summary>
        public override TokenValueAst? VisitPhpExprUnaryPreOpsGrammarAddon([NotNull] TyhpParser.PhpExprUnaryPreOpsGrammarAddonContext context)
            => this.GetTokenValueAst(context, context.TokenValue);


        /// <summary>
        /// reservedNonModifiersGrammarAddon
        ///     : tyhpReservedNonModifiers {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override TokenValueAst VisitReservedNonModifiersGrammarAddon([NotNull] TyhpParser.ReservedNonModifiersGrammarAddonContext context)
            => this.VisitTyhpReservedNonModifiers(context.tyhpReservedNonModifiers());

        /// <summary>
        /// Overrides the grammar addon handler for return types.
        /// The PHP visitor's handler calls the non-virtual VisitReturnTypeGrammarAddon
        /// which throws. This override dispatches to the Tyhp-specific return type guard.
        ///
        /// Grammar (PHP):
        ///   returnType
        ///     : (T_SYM_COLON TypeExpr=typeExpr)?              #returnTypeType
        ///     | returnTypeGrammarAddon                         #returnTypeGrammarAddonHandler
        ///     ;
        ///
        /// Grammar (Tyhp override):
        ///   returnTypeGrammarAddon
        ///     : T_SYM_COLON GuardVariable=T_VARIABLE
        ///         ('[' index ']')? (T_INSTANCEOF|T_TYHP_IS)
        ///         TypeExpr=typeExpr {this.isLanguageMode("tyhp")}?   #tyhpReturnTypeGuard
        ///     ;
        /// </summary>
        public override ITypeExpression VisitReturnTypeGrammarAddonHandler([NotNull] TyhpParser.ReturnTypeGrammarAddonHandlerContext context)
            => context.returnTypeGrammarAddon() switch
            {
                TyhpParser.TyhpReturnTypeGuardContext guard => this.VisitTyhpReturnTypeGuard(guard),
                null => ErrorAst.Create(context, GetCurrentLanguageMode(context)),
                var addon => (this.Visit(addon) as ITypeExpression)
                    ?? UnexpectedNodeAst.Create(addon)
                    ?? UnexpectedNodeAst.Create(context),
            };


        /// <summary>
        /// Visits a Tyhp return type guard: <c>: $variable is SomeType</c> or
        /// <c>: $array[$key] is SomeType</c>.
        /// </summary>
        public override TyhpReturnTypeGuardAst VisitTyhpReturnTypeGuard([NotNull] TyhpParser.TyhpReturnTypeGuardContext context)
        {
            ITypeExpression typeExpr = context.TypeExpr != null
                ? this.VisitTypeExpr(context.TypeExpr)
                : ErrorAst.Create(context, GetCurrentLanguageMode(context));

            var baseVar = PhpVariableAst.Create(
                this.GetTokenValueAst(context, context.GuardVariable),
                false,
                context);

            var indexExpr = TryVisitTypeGuardIndex(context);
            IExpression subject = indexExpr is null
                ? baseVar
                : PhpDereferenceableAst.Create(
                    baseVar,
                    PhpArrayAccessAst.Create(indexExpr, context),
                    context);

            return TyhpReturnTypeGuardAst.Create(subject, typeExpr, context);
        }


        /// <summary>
        /// semiReservedGrammarAddon
        ///     : tyhpSemiReserved {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override TokenValueAst VisitSemiReservedGrammarAddon([NotNull] TyhpParser.SemiReservedGrammarAddonContext context)
            => this.VisitTyhpSemiReserved(context.tyhpSemiReserved());

        /// <summary>
        /// Override the statement requiring terminal grammar addon to dispatch
        /// to the Tyhp typed variable expression handler.
        ///
        /// Grammar (TyhpParser.g4):
        ///   statementRequiringTerminalGrammarAddon
        ///       : Statement=tyhpTypedVarExpr {this.isLanguageMode("tyhp")}?   #tyhpStatementTypedVarExpr
        ///       ;
        /// </summary>
        public override IStatement VisitStatementRequiringTerminalGrammarAddon(
            [NotNull] TyhpParser.StatementRequiringTerminalGrammarAddonContext context)
            => context switch
            {
                TyhpParser.TyhpStatementTypedVarExprContext typedVarExpr
                    => this.VisitTyhpStatementTypedVarExpr(typedVarExpr),
                _ => base.VisitStatementRequiringTerminalGrammarAddon(context),
            };


        /// <summary>
        /// Visit the labeled alternative #tyhpStatementTypedVarExpr.
        /// Delegates to VisitTyhpTypedVarExpr for the actual typed variable expression.
        ///
        /// Grammar:
        ///   #tyhpStatementTypedVarExpr
        ///       : Statement=tyhpTypedVarExpr {this.isLanguageMode("tyhp")}?
        /// </summary>
        public override TyhpTypedVarExprAst VisitTyhpStatementTypedVarExpr(
            [NotNull] TyhpParser.TyhpStatementTypedVarExprContext context)
        {
            if (context.Statement == null)
            {
                this.ReportMissingRequired(context, "tyhpStatementTypedVarExpr.Statement");
                return TyhpTypedVarExprAst.Create(
                    PhpTypeExpressionAst.CreateError(context, GetCurrentLanguageMode(context)),
                    PhpVariableAst.CreateError(context, GetCurrentLanguageMode(context)),
                    null,
                    false,
                    false,
                    context);
            }

            return this.VisitTyhpTypedVarExpr(context.Statement);
        }


        /// <summary>
        /// Visit a statement without a terminal grammar addon (tyhp-specific statements).
        /// Routes tyhpUsingBlock to the Tyhp using block handler.
        ///
        /// Grammar (TyhpParser.g4):
        ///   statementWithoutTerminalGrammarAddon
        ///       : Statement=tyhpUsingBlock {this.isLanguageMode("tyhp")}?   #tyhpStatementUsingBlock
        ///       ;
        /// </summary>
        public override IStatement VisitStatementWithoutTerminalGrammarAddon(
            [NotNull] TyhpParser.StatementWithoutTerminalGrammarAddonContext context)
            => context switch
            {
                TyhpParser.TyhpStatementUsingBlockContext usingCtx
                    => this.VisitTyhpUsingBlock(usingCtx.Statement),
                _ => base.VisitStatementWithoutTerminalGrammarAddon(context),
            };


        //#endregion Class Statement Grammar Addon

        //#region Trait Alias Grammar Addon

        /// <summary>
        /// Dispatches trait alias grammar addon alternatives.
        /// Overrides the PhpParserAstVisitor's throwing implementation.
        ///
        /// Grammar (TyhpParser):
        ///   traitAliasGrammarAddon
        ///     : AliasOf=traitPropertyReference T_AS AliasString=T_VARIABLE
        ///         {this.isLanguageMode("tyhp")}?          #tyhpTraitAliasPropertyRename
        ///     ;
        /// </summary>
        public override PhpTraitAliasAst VisitTraitAliasGrammarAddon([NotNull] TyhpParser.TraitAliasGrammarAddonContext context)
        {
            return context switch
            {
                TyhpParser.TyhpTraitAliasPropertyRenameContext ctx => this.VisitTyhpTraitAliasPropertyRename(ctx),
                TyhpParser.TyhpTraitAliasHideContext ctx => this.VisitTyhpTraitAliasHide(ctx),
                _ => HandleUnexpectedAlternativeSpecial(context, "traitAliasGrammarAddon",
                    () => PhpTraitAliasAst.CreateError(context, GetCurrentLanguageMode(context)))
            };
        }


        /// <summary>
        /// Visits a postfix <c>hide</c> adaptation inside <c>use extension { }</c>
        /// (<c>Foo::bar hide;</c> / <c>operator *&lt;string&gt; hide;</c>).
        /// </summary>
        public override PhpTraitAliasAst VisitTyhpTraitAliasHide([NotNull] TyhpParser.TyhpTraitAliasHideContext context)
        {
            PhpTraitMemberRefAst aliasOf;
            if (context.AliasOf != null)
            {
                aliasOf = this.VisitTraitMethodReference(context.AliasOf);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpTraitAliasHide.AliasOf");
                aliasOf = PhpTraitMemberRefAst.Create(
                    PhpNameAst.CreateError(context, GetCurrentLanguageMode(context)),
                    context,
                    GetCurrentLanguageMode(context));
            }

            return PhpTraitAliasAst.CreateHide(aliasOf, context, GetCurrentLanguageMode(context));
        }


        /// <summary>
        /// Visits a trait alias property rename declaration.
        /// This is a Tyhp extension that allows renaming trait properties
        /// (not just methods) when using traits.
        ///
        /// Grammar:
        ///   traitAliasGrammarAddon
        ///     : AliasOf=traitPropertyReference T_AS AliasString=T_VARIABLE
        ///         {this.isLanguageMode("tyhp")}?          #tyhpTraitAliasPropertyRename
        ///     ;
        ///
        /// Creates a PhpTraitAliasAst with the property reference and the
        /// new variable name (AliasString is a T_VARIABLE token).
        /// </summary>
        public override PhpTraitAliasAst VisitTyhpTraitAliasPropertyRename([NotNull] TyhpParser.TyhpTraitAliasPropertyRenameContext context)
        {
            var aliasOf = this.VisitTraitPropertyReference(context.AliasOf);
            var newName = context.AliasString.Text;

            return PhpTraitAliasAst.Create(
                aliasOf,
                newName,
                context,
                GetCurrentLanguageMode(context)
            );
        }


        //#endregion Trait Alias Grammar Addon

        //#region Identifier and Name Grammar Addons

        /// <summary>
        /// Visits the trait alias name grammar addon, returning generic type
        /// arguments if present.
        ///
        /// Grammar (TyhpParser):
        ///   traitAliasNameGrammarAddon
        ///     : GenericArguments=tyhpGenericTypeArguments?
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override IBase2Ast? VisitTraitAliasNameGrammarAddon([NotNull] TyhpParser.TraitAliasNameGrammarAddonContext context)
            => context.GenericArguments != null
                ? this.VisitTyhpGenericTypeArguments(context.GenericArguments)
                : null;


        /// <summary>
        /// Visits the trait method identifier grammar addon, returning a generic
        /// identifier if present.
        ///
        /// Grammar (TyhpParser):
        ///   traitMethodIdentifierGrammarAddon
        ///     : (GenericIdentifier=tyhpGenericIdentifier
        ///         {this.isLanguageMode("tyhp")}?)?
        ///     ;
        /// </summary>
        public override IBase2Ast? VisitTraitMethodIdentifierGrammarAddon([NotNull] TyhpParser.TraitMethodIdentifierGrammarAddonContext context)
            => context.GenericIdentifier != null
                ? this.VisitTyhpGenericIdentifier(context.GenericIdentifier)
                : null;


        public override PhpTraitMemberRefAst VisitTraitMethodReferenceGrammarAddon(
            [NotNull] TyhpParser.TraitMethodReferenceGrammarAddonContext context)
            => context switch
            {
                TyhpParser.TyhpTraitOperatorMethodReferenceContext ctx
                    => this.VisitTyhpTraitOperatorMethodReference(ctx),
                _ => base.VisitTraitMethodReferenceGrammarAddon(context)
            };


        /// <summary>
        /// Unqualified <c>operator *&lt;string&gt;</c> (and <c>operator *</c>) inside
        /// <c>use extension { … }</c> adaptations.
        /// </summary>
        public override PhpTraitMemberRefAst VisitTyhpTraitOperatorMethodReference(
            [NotNull] TyhpParser.TyhpTraitOperatorMethodReferenceContext context)
            => this.BuildOperatorTraitMemberRef(
                traitName: null,
                op: context.Op,
                targetType: context.TargetType,
                context);


        public override PhpModifierListAst? VisitTraitModifiersGrammarAddon([NotNull] TyhpParser.TraitModifiersGrammarAddonContext context)
            => this.VisitOptionalInternalModifierList(context, context.IsInternal);


        /// <summary>
        /// Visits the trait name grammar addon, returning generic type arguments
        /// if present in Tyhp mode.
        ///
        /// Grammar (TyhpParser):
        ///   traitNameGrammarAddon
        ///     : GenericArguments=tyhpGenericParameterDeclarations?
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override IBase2Ast? VisitTraitNameGrammarAddon([NotNull] TyhpParser.TraitNameGrammarAddonContext context)
            => context.GenericArguments != null
                ? this.VisitTyhpGenericParameterDeclarations(context.GenericArguments)
                : null;

        /// <summary>
        /// Visits an anonymous struct declaration (used with `new struct { ... }`).
        ///
        /// Grammar:
        ///   tyhpAnonymousStruct
        ///     : StructKw=T_STRING {this.isStructKeyword($StructKw)}?
        ///         (T_EXTENDS Extends=className)? (T_OPEN_ROUND_BRACE
        ///         T_CLOSE_ROUND_BRACE)? FindDocComment=T_OPEN_CURLY_BRACE
        ///         PropertyList=tyhpStructPropertyList T_CLOSE_CURLY_BRACE
        ///     ;
        /// </summary>
        public override TyhpStructDeclAst VisitTyhpAnonymousStruct([NotNull] TyhpParser.TyhpAnonymousStructContext context)
        {
            var docComment = this.FindPossibleDocComment(context.FindDocComment);

            TyhpStructPropertyListAst propertyList;
            if (context.PropertyList != null)
            {
                propertyList = this.VisitTyhpStructPropertyList(context.PropertyList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpAnonymousStruct.PropertyList");
                propertyList = TyhpStructPropertyListAst.Create(null, context);
            }

            return TyhpStructDeclAst.Create(
                null,
                propertyList,
                context.Extends != null ? this.VisitClassName(context.Extends) : null,
                docComment,
                context
            );
        }


        /// <summary>
        /// Visits a Tyhp class method definition (function keyword variant).
        /// Called by ANTLR dispatch when Visit() is used on a TyhpClassMethodContext.
        ///
        /// Grammar:
        ///   tyhpClassMethodDefinition
        ///     : function ReturnsRef=returnsRef tyhpMethodDefinition  #tyhpClassMethod
        ///     ;
        ///
        /// Note: When called standalone (not via VisitAttributedClassStatementGrammarAddon),
        /// modifiers will be null since they live on the parent context.
        /// </summary>
        public override PhpMethodDeclAst VisitTyhpClassMethod([NotNull] TyhpParser.TyhpClassMethodContext context)
            => this.CreateTyhpClassMethod(context, null);


        /// <summary>
        /// Visits a Tyhp short (arrow) class method definition.
        /// Called by ANTLR dispatch when Visit() is used on a TyhpClassGenericMethodShortContext.
        ///
        /// Grammar:
        ///   tyhpClassMethodDefinition
        ///     : fn ReturnsRef=returnsRef
        ///         GenericIdentifier=tyhpGenericIdentifierWithoutConstructor
        ///         FindDocComment=T_OPEN_ROUND_BRACE ParameterList=parameterList
        ///         T_CLOSE_ROUND_BRACE OptionalReturnType=returnType T_DOUBLE_ARROW
        ///         Expr=expr T_SYM_SEMICOLON {this.isLanguageMode("tyhp")}?
        ///                                                            #tyhpClassGenericMethodShort
        ///     ;
        ///
        /// Note: When called standalone, modifiers will be null.
        /// </summary>
        public override PhpMethodDeclAst VisitTyhpClassGenericMethodShort([NotNull] TyhpParser.TyhpClassGenericMethodShortContext context)
            => this.CreateTyhpClassGenericMethodShort(context, null);


        /// <summary>
        /// Visits the operator token in an operator overload declaration.
        ///
        /// Grammar:
        ///   tyhpClassOperatorOverloadOp
        ///     : TokenValue=T_SYM_PLUS
        ///     | TokenValue=T_SYM_MINUS
        ///     | ... (many operator token alternatives)
        ///     | TokenValue=T_STRING   // for true, false, empty, null, convert
        ///     ;
        ///
        /// Returns a TokenValueAst holding the operator's text and token type.
        /// </summary>
        public override TokenValueAst VisitTyhpClassOperatorOverloadOp([NotNull] TyhpParser.TyhpClassOperatorOverloadOpContext context)
        {
            if (context.TokenValue == null)
            {
                this.ReportMissingRequired(context, "tyhpClassOperatorOverloadOp.TokenValue");
                return TokenValueAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            return context.TokenValue.Type == TyhpLang.Parser.TyhpParser.T_SYM_GT && context.IsSR?.Type == TyhpLang.Parser.TyhpParser.T_SYM_GT ?
                TokenValueAst.Create(">>", TyhpLang.Parser.TyhpParser.T_SR, context) :
                this.GetTokenValueAst(context, context.TokenValue);
        }


        //#endregion Name Grammar Addons

        //#region Tyhp Constructor Return Type

        /// <summary>
        /// Visits a Tyhp constructor return type annotation.
        ///
        /// Grammar:
        ///   tyhpCtorReturnType
        ///     : T_SYM_COLON TokenValue=T_TYHP_VOID
        ///     | T_SYM_COLON TokenValue=T_TYHP_PARENT ArgumentsList=argumentList
        ///     ;
        ///
        /// This rule is referenced optionally from `tyhpClassCtorWithReturnType`
        /// (`ReturnType=tyhpCtorReturnType?`). Omitting the annotation is equivalent
        /// to `: void` (no `parent::__construct` insertion); this visitor is only
        /// reached when the author wrote an explicit `: void` or `: parent(...)`.
        ///
        /// Returns a TyhpCtorReturnTypeAst with the type token and optional
        /// argument list for parent constructor delegation, or null when ANTLR error
        /// recovery entered this rule (e.g. `: int`) without matching `T_TYHP_VOID` /
        /// `T_TYHP_PARENT` — the parser already reported the real syntax diagnostic, so
        /// the caller treats a null result the same as an omitted annotation instead of
        /// throwing on the missing token.
        /// </summary>
        public override TyhpCtorReturnTypeAst? VisitTyhpCtorReturnType([NotNull] TyhpParser.TyhpCtorReturnTypeContext context)
        {
            var typeToken = this.GetTokenValueAst(context, context.TokenValue);
            if (typeToken is null)
            {
                return null;
            }

            var arguments = context.ArgumentsList != null
                ? this.VisitArgumentList(context.ArgumentsList)
                : null;

            return TyhpCtorReturnTypeAst.Create(typeToken, arguments, context);
        }


        /// <summary>
        /// Grammar: #tyhpExtensionFunctionDecl — brace or bodyless <c>function</c> member.
        /// Name is <c>tyhpOptionalGenericIdentifierWithoutConstructor</c> (method-style).
        /// </summary>
        public override PhpFunctionDeclAst VisitTyhpExtensionFunctionDecl(
            [NotNull] TyhpParser.TyhpExtensionFunctionDeclContext context)
        {
            var languageMode = GetCurrentLanguageMode(context);
            var docComment = this.FindPossibleDocComment(context.FindDocComment);

            PhpStatementBlockAst? body;
            if (context.StatementList != null)
            {
                body = this.VisitMethodBody(context.StatementList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpExtensionFunctionDecl.StatementList");
                body = null;
            }

            var ast = this.CreateLiveExtensionFunctionDecl(
                context,
                context.GenericIdentifier,
                context.ReturnsRef,
                context.functionModifiersGrammarAddon(),
                context.Parameters,
                context.ReturnType,
                body,
                isShortSyntax: false,
                languageMode,
                docComment);

            if (body == null && context.StatementList != null)
            {
                ast.AddGrammarAddon(
                    "isOverloadSignature",
                    this.GetTokenValueAst(context, context.StatementList.Start));
            }

            return ast.WithAttributes(
                context.Attributes != null ? this.VisitAttributes(context.Attributes) : null);
        }


        /// <summary>
        /// Grammar: #tyhpExtensionFunctionShortDecl — <c>fn name(...) =&gt; expr;</c>.
        /// Desugars to <c>return expr;</c> and must not carry <c>isOverloadSignature</c>.
        /// </summary>
        public override PhpFunctionDeclAst VisitTyhpExtensionFunctionShortDecl(
            [NotNull] TyhpParser.TyhpExtensionFunctionShortDeclContext context)
        {
            var languageMode = GetCurrentLanguageMode(context);
            var docComment = this.FindPossibleDocComment(context.FindDocComment);

            IExpression expr;
            if (context.Expr != null)
            {
                expr = this.VisitExpr(context.Expr);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpExtensionFunctionShortDecl.Expr");
                expr = ErrorAst.Create(context, languageMode);
            }

            var body = PhpStatementBlockAst.Create(
                [PhpUnaryOpAst.Create(
                    TokenValueAst.Create("return", TyhpParser.T_RETURN, context),
                    expr,
                    context,
                    languageMode
                )],
                context,
                languageMode
            );

            return this.CreateLiveExtensionFunctionDecl(
                    context,
                    context.GenericIdentifier,
                    context.ReturnsRef,
                    context.functionModifiersGrammarAddon(),
                    context.Parameters,
                    context.OptionalReturnType,
                    body,
                    isShortSyntax: true,
                    languageMode,
                    docComment)
                .WithAttributes(
                    context.Attributes != null ? this.VisitAttributes(context.Attributes) : null);
        }


        private IExtensionMemberAst VisitExtensionCallableMember(
            TyhpParser.TyhpExtensionCallableMemberContext? member,
            ParserRuleContext owner)
        {
            return member switch
            {
                TyhpParser.TyhpExtensionFunctionDeclContext ctx => this.VisitTyhpExtensionFunctionDecl(ctx),
                TyhpParser.TyhpExtensionFunctionShortDeclContext ctx => this.VisitTyhpExtensionFunctionShortDecl(ctx),
                null => this.ReportMissingRequiredAsErrorAst(owner, "tyhpExtensionCallableMember"),
                _ => this.HandleUnexpectedAlternativeSpecial<IExtensionMemberAst>(
                    member,
                    "tyhpExtensionCallableMember",
                    () => ErrorAst.Create(member, GetCurrentLanguageMode(member)))
            };
        }

        /// <summary>
        /// Visits a Tyhp extension declaration statement.
        ///
        /// Grammar:
        ///   tyhpExtensionDeclarationStatement
        ///     : T_TYHP_INTERNAL? T_TYHP_EXTENSION Identifier=T_STRING
        ///         GenericParameters=tyhpGenericParameterDeclarations?
        ///         (T_EXTENDS TargetType=typeExprWithoutStatic)?
        ///         FindDocComment=T_OPEN_CURLY_BRACE FunctionList=tyhpExtensionFunctionList
        ///         T_CLOSE_CURLY_BRACE
        ///     ;
        ///
        /// Creates a TyhpExtensionDeclAst with the extension name, optional generic
        /// parameters, optional header target, member list (functions, operators,
        /// and nested groups), and an optional doc comment.
        /// </summary>
        public override TyhpExtensionDeclAst VisitTyhpExtensionDeclarationStatement([NotNull] TyhpParser.TyhpExtensionDeclarationStatementContext context)
        {
            var docComment = this.FindPossibleDocComment(context.FindDocComment);

            // Truncated `extension Foo` at EOF leaves FunctionList (and sometimes Identifier)
            // null after ANTLR recovery — same pattern as object-type decls.
            string name;
            if (context.Identifier != null)
            {
                name = context.Identifier.Text;
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpExtensionDeclarationStatement.Identifier");
                name = "<error>";
            }

            TyhpExtensionFunctionListAst functionList;
            if (context.FunctionList != null)
            {
                functionList = this.VisitTyhpExtensionFunctionList(context.FunctionList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpExtensionDeclarationStatement.FunctionList");
                functionList = TyhpExtensionFunctionListAst.Create(null, context);
            }

            var result = TyhpExtensionDeclAst.Create(
                name,
                functionList,
                docComment,
                context
            );
            this.AttachExtensionBlockTarget(result, context.GenericParameters, context.TargetType);
            if (context.IsInternal != null)
            {
                result.AddGrammarAddon("isInternal", TokenValueAst.Create(context.IsInternal, context));
            }

            return result;
        }


        /// <summary>
        /// Visits <see cref="TyhpParser.tyhpExtensionFunctionList"/>.
        /// </summary>
        public override TyhpExtensionFunctionListAst VisitTyhpExtensionFunctionList([NotNull] TyhpParser.TyhpExtensionFunctionListContext context)
            => TyhpExtensionFunctionListAst.Create(
                (context.tyhpExtensionMember() ?? Enumerable.Empty<TyhpParser.TyhpExtensionMemberContext>())
                    .Select(this.VisitTyhpExtensionMemberAsExtensionMember),
                context
            );


        private IExtensionMemberAst VisitTyhpExtensionGroupMemberAsExtensionMember(
            TyhpParser.TyhpExtensionGroupMemberContext context)
        {
            return context switch
            {
                TyhpParser.TyhpExtensionGroupCallableMemberContext ctx =>
                    this.VisitExtensionCallableMember(ctx.Member, context),
                TyhpParser.TyhpExtensionGroupOperatorMemberContext ctx =>
                    this.VisitExtensionOperatorMember(ctx.Attributes, ctx.OperatorOverload, context),
                _ => this.HandleUnexpectedAlternativeSpecial<IExtensionMemberAst>(
                    context,
                    "tyhpExtensionGroupMember",
                    () => ErrorAst.Create(context, GetCurrentLanguageMode(context)))
            };
        }


        public override TyhpExtensionFunctionListAst VisitTyhpExtensionGroupMemberList(
            [NotNull] TyhpParser.TyhpExtensionGroupMemberListContext context)
            => TyhpExtensionFunctionListAst.Create(
                (context.tyhpExtensionGroupMember() ?? [])
                    .Select(this.VisitTyhpExtensionGroupMemberAsExtensionMember),
                context);


        /// <summary>
        /// Dispatches <c>tyhpExtensionMember</c> labeled alternatives (no unlabeled base
        /// rule visitor is generated since every alternative carries a label).
        /// Function / <c>fn</c> members use method-style names via
        /// <c>tyhpOptionalGenericIdentifierWithoutConstructor</c>.
        /// Copies member <c>#[…]</c> onto the function / operator the same way
        /// <c>VisitTyhpdefStandaloneExtensionFunctionDecl</c> does.
        /// </summary>
        private IExtensionMemberAst VisitTyhpExtensionMemberAsExtensionMember(TyhpParser.TyhpExtensionMemberContext context)
        {
            return context switch
            {
                TyhpParser.TyhpExtensionCallableMemberAltContext ctx =>
                    this.VisitExtensionCallableMember(ctx.Member, context),
                TyhpParser.TyhpExtensionOperatorMemberContext ctx => this.VisitTyhpExtensionOperatorMember(ctx),
                TyhpParser.TyhpExtensionTargetGroupMemberContext ctx =>
                    this.VisitExtensionTargetGroupMember(ctx.TargetGroup, context),
                _ => this.HandleUnexpectedAlternativeSpecial<IExtensionMemberAst>(
                    context,
                    "tyhpExtensionMember",
                    () => ErrorAst.Create(context, GetCurrentLanguageMode(context)))
            };
        }


        /// <summary>
        /// Grammar: #tyhpExtensionOperatorMember — attributes wrapping
        /// <c>tyhpExtensionOperatorOverload</c>.
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpExtensionOperatorMember(
            [NotNull] TyhpParser.TyhpExtensionOperatorMemberContext context)
        {
            var attributes = context.Attributes != null
                ? this.VisitAttributes(context.Attributes)
                : null;

            TyhpParser.TyhpExtensionOperatorOverloadContext? opOverload = context.tyhpExtensionOperatorOverload();
            if (opOverload == null)
            {
                this.ReportMissingRequired(context, "tyhpExtensionOperatorMember.tyhpExtensionOperatorOverload");
                return TyhpOperatorOverloadAst.CreateError(context, GetCurrentLanguageMode(context))
                    .WithAttributes(attributes);
            }

            return this.VisitTyhpExtensionOperatorOverload(opOverload).WithAttributes(attributes);
        }


        /// <summary>
        /// Grammar: tyhpExtensionOperatorOverload — operands only. A
        /// <c>&lt;Type&gt;</c> after the operator token is the old declaration spelling.
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpExtensionOperatorOverload(
            [NotNull] TyhpParser.TyhpExtensionOperatorOverloadContext context)
        {
            var languageMode = GetCurrentLanguageMode(context);
            this.ReportLegacyOperatorTarget(context.LegacyTarget, context);
            var op = this.VisitTyhpClassOperatorOverloadOp(context.Op);
            var leftParam = this.VisitAttributedParameter(context.LeftParameter);
            var rightParam = context.RightParameter != null
                ? this.VisitAttributedParameter(context.RightParameter)
                : null;
            var returnType = this.VisitReturnType(context.ConvertReturnType);

            PhpStatementBlockAst? body;
            if (context.StatementList != null)
            {
                body = this.VisitMethodBody(context.StatementList);
            }
            else if (context.ShorthandExpr != null)
            {
                var expr = this.VisitExpr(context.ShorthandExpr);
                body = PhpStatementBlockAst.Create(
                    [PhpUnaryOpAst.Create(
                        TokenValueAst.Create("return", TyhpParser.T_RETURN, context),
                        expr,
                        context,
                        languageMode
                    )],
                    context,
                    languageMode
                );
            }
            else
            {
                body = null;
            }

            var ast = TyhpOperatorOverloadAst.Create(
                op,
                leftParam,
                rightParam,
                returnType,
                body,
                null,
                context,
                languageMode,
                isShortSyntax: context.ShorthandExpr != null);

            if (context.IsInternal != null)
            {
                ast.AddGrammarAddon("isInternal", TokenValueAst.Create(context.IsInternal, context));
            }

            return ast;
        }


        /// <summary>
        /// Visits a nested <c>extends Type { }</c> group as an extension member.
        /// </summary>
        public override TyhpExtensionDeclAst VisitTyhpExtensionTargetGroup(
            [NotNull] TyhpParser.TyhpExtensionTargetGroupContext context)
            => this.CreateExtensionTargetGroup(
                context,
                context.GenericParameters,
                context.TargetType,
                context.FindDocComment,
                context.FunctionList != null
                    ? this.VisitTyhpExtensionGroupMemberList(context.FunctionList)
                    : null);


        private IExtensionMemberAst VisitExtensionTargetGroupMember(
            TyhpParser.TyhpExtensionTargetGroupContext? group,
            ParserRuleContext owner)
        {
            if (group == null)
            {
                this.ReportMissingRequired(owner, "tyhpExtensionTargetGroup");
                return TyhpExtensionDeclAst.CreateError(owner, GetCurrentLanguageMode(owner));
            }

            return this.VisitTyhpExtensionTargetGroup(group);
        }

        /// <summary>
        /// tyhpGenericIdentifier
        ///     : (Identifier=T_STRING | IdentifierSemiReserved=semiReserved)
        ///         GenericArguments=tyhpGenericTypeArguments
        ///     ;
        /// </summary>
        public override TyhpGenericIdentifierAst VisitTyhpGenericIdentifier([NotNull] TyhpParser.TyhpGenericIdentifierContext context)
        {
            PhpTypeExpressionListAst genericArgs;
            if (context.GenericArguments != null)
            {
                genericArgs = this.VisitTyhpGenericTypeArguments(context.GenericArguments);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpGenericIdentifier.GenericArguments");
                genericArgs = PhpTypeExpressionListAst.Create(null, context);
            }

            if (context.Identifier != null)
            {
                return TyhpGenericIdentifierAst.Create(context.Identifier, genericArgs, context);
            }

            if (context.IdentifierSemiReserved == null)
            {
                this.ReportMissingRequired(context, "tyhpGenericIdentifier.Identifier");
                return TyhpGenericIdentifierAst.Create("<error>", -1, genericArgs, context);
            }

            var semiReserved = this.VisitSemiReserved(context.IdentifierSemiReserved);
            return TyhpGenericIdentifierAst.Create(semiReserved.ValueString ?? "", 0, genericArgs, context);
        }


        /// <summary>
        /// tyhpGenericIdentifierWithoutConstructor
        ///     : (Identifier=T_STRING | IdentifierSemiReserved=semiReservedWithoutConstructor)
        ///         GenericArguments=tyhpGenericParameterDeclarations
        ///     ;
        /// </summary>
        public override TyhpGenericIdentifierAst VisitTyhpGenericIdentifierWithoutConstructor([NotNull] TyhpParser.TyhpGenericIdentifierWithoutConstructorContext context)
        {
            TyhpGenericsTypeArgumentListAst genericParams;
            if (context.GenericArguments != null)
            {
                genericParams = this.VisitTyhpGenericParameterDeclarations(context.GenericArguments);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpGenericIdentifierWithoutConstructor.GenericArguments");
                genericParams = TyhpGenericsTypeArgumentListAst.Create(null, context);
            }

            if (context.Identifier != null)
            {
                return TyhpGenericIdentifierAst.Create(context.Identifier, genericParams, context);
            }

            if (context.IdentifierSemiReserved == null)
            {
                this.ReportMissingRequired(context, "tyhpGenericIdentifierWithoutConstructor.Identifier");
                return TyhpGenericIdentifierAst.Create("<error>", -1, genericParams, context);
            }

            var semiReserved = this.VisitSemiReservedWithoutConstructor(context.IdentifierSemiReserved);
            return TyhpGenericIdentifierAst.Create(semiReserved.ValueString ?? "", 0, genericParams, context);
        }


        /// <summary>
        /// tyhpGenericParameterDeclaration
        ///     : Identifier=name (T_EXTENDS TypeExpr=typeExpr)? (T_SYM_EQUAL DefaultExpr=typeExpr)?
        ///     ;
        /// </summary>
        public override TyhpGenericsTypeArgumentAst VisitTyhpGenericParameterDeclaration([NotNull] TyhpParser.TyhpGenericParameterDeclarationContext context)
        {
            PhpNameAst name;
            if (context.Identifier != null)
            {
                name = this.VisitName(context.Identifier);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpGenericParameterDeclaration.Identifier");
                name = PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var typeConstraint = context.TypeExpr != null ? this.VisitTypeExpr(context.TypeExpr) : null;
            var defaultType = context.DefaultExpr != null ? this.VisitTypeExpr(context.DefaultExpr) : null;
            return TyhpGenericsTypeArgumentAst.Create(name, typeConstraint, defaultType, context);
        }


        /// <summary>
        /// tyhpGenericParameterDeclarationList
        ///     : Items+=tyhpGenericParameterDeclaration (T_SYM_COMMA Items+=tyhpGenericParameterDeclaration)*
        ///     ;
        /// </summary>
        public override TyhpGenericsTypeArgumentListAst VisitTyhpGenericParameterDeclarationList([NotNull] TyhpParser.TyhpGenericParameterDeclarationListContext context)
            => TyhpGenericsTypeArgumentListAst.Create(
                context._Items?.Select(this.VisitTyhpGenericParameterDeclaration),
                context
            );


        /// <summary>
        /// tyhpGenericParameterDeclarations
        ///     : T_SYM_LT GenericParametersList=tyhpGenericParameterDeclarationList T_SYM_GT
        ///     ;
        /// </summary>
        public override TyhpGenericsTypeArgumentListAst VisitTyhpGenericParameterDeclarations([NotNull] TyhpParser.TyhpGenericParameterDeclarationsContext context)
        {
            if (context.GenericParametersList == null)
            {
                this.ReportMissingRequired(context, "tyhpGenericParameterDeclarations.GenericParametersList");
                return TyhpGenericsTypeArgumentListAst.Create(null, context);
            }

            return this.VisitTyhpGenericParameterDeclarationList(context.GenericParametersList);
        }


        /// <summary>
        /// tyhpGenericTypeArgument
        ///     : TypeExpr=typeExpr PostfixEllipsis=T_ELLIPSIS?
        ///     | WildcardEllipsis=T_ELLIPSIS
        ///     ;
        /// </summary>
        public override ITypeExpression VisitTyhpGenericTypeArgument([NotNull] TyhpParser.TyhpGenericTypeArgumentContext context)
        {
            if (context.WildcardEllipsis != null)
            {
                return TyhpEllipsisTypeAst.Create(context, GetCurrentLanguageMode(context));
            }

            if (context.TypeExpr == null)
            {
                this.ReportMissingRequired(context, "tyhpGenericTypeArgument.TypeExpr");
                return PhpTypeExpressionAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var inner = this.VisitTypeExpr(context.TypeExpr);
            if (context.PostfixEllipsis != null)
            {
                return TyhpPostfixEllipsisTypeAst.Create(inner, context, GetCurrentLanguageMode(context));
            }

            return inner;
        }


        /// <summary>
        /// tyhpGenericTypeArgumentList
        ///     : Items+=tyhpGenericTypeArgument (T_SYM_COMMA Items+=tyhpGenericTypeArgument)*
        ///     ;
        /// </summary>
        public override PhpTypeExpressionListAst VisitTyhpGenericTypeArgumentList([NotNull] TyhpParser.TyhpGenericTypeArgumentListContext context)
            => PhpTypeExpressionListAst.Create(
                context._Items?.Select(item => this.VisitTyhpGenericTypeArgument(item)),
                context
            );


        /// <summary>
        /// tyhpGenericTypeArguments
        ///     : T_SYM_LT GenericArgumentsList=tyhpGenericTypeArgumentList T_SYM_GT
        ///     ;
        /// </summary>
        public override PhpTypeExpressionListAst VisitTyhpGenericTypeArguments([NotNull] TyhpParser.TyhpGenericTypeArgumentsContext context)
        {
            if (context.GenericArgumentsList == null)
            {
                this.ReportMissingRequired(context, "tyhpGenericTypeArguments.GenericArgumentsList");
                return PhpTypeExpressionListAst.Create(null, context);
            }

            return this.VisitTyhpGenericTypeArgumentList(context.GenericArgumentsList);
        }


        /// <summary>
        /// Visits a Tyhp constructor with explicit return type.
        /// Called by ANTLR dispatch when Visit() is used on a TyhpClassCtorWithReturnTypeContext.
        ///
        /// Grammar:
        ///   tyhpMethodDefinition
        ///     : Identifier=T_CONSTRUCT_METHOD
        ///         FindDocComment=T_OPEN_ROUND_BRACE ParameterList=ctorParameterList
        ///         T_CLOSE_ROUND_BRACE ReturnType=tyhpCtorReturnType?
        ///         StatementList=methodBody                            #tyhpClassCtorWithReturnType
        ///     ;
        ///
        /// The return type annotation is optional: omitting it is equivalent to `: void`
        /// (no `parent::__construct` insertion). When omitted, no `ctorReturnType` grammar
        /// addon is attached; the emitter and checker treat a missing addon as void.
        ///
        /// Note: When called standalone, modifiers and returnsRef will be defaults.
        /// </summary>
        public override PhpMethodDeclAst VisitTyhpClassCtorWithReturnType([NotNull] TyhpParser.TyhpClassCtorWithReturnTypeContext context)
            => this.CreateTyhpClassCtor(context, false, null);


        /// <summary>
        /// Visits a Tyhp generic class method definition.
        /// Called by ANTLR dispatch when Visit() is used on a TyhpClassGenericMethodContext.
        ///
        /// Grammar:
        ///   tyhpMethodDefinition
        ///     : GenericIdentifier=tyhpGenericIdentifierWithoutConstructor
        ///         FindDocComment=T_OPEN_ROUND_BRACE ParameterList=parameterList
        ///         T_CLOSE_ROUND_BRACE ReturnType=returnType
        ///         StatementList=methodBody                            #tyhpClassGenericMethod
        ///     ;
        ///
        /// Note: When called standalone, modifiers and returnsRef will be defaults.
        /// </summary>
        public override PhpMethodDeclAst VisitTyhpClassGenericMethod([NotNull] TyhpParser.TyhpClassGenericMethodContext context)
            => this.CreateTyhpClassGenericMethod(context, false, null);


        /// <summary>
        /// Visits <c>object { … }</c> on a type-alias RHS. Members reuse the tyhpdef
        /// class statement list (signatures only) plus PHP class-const spelling
        /// (<c>const NAME = expr</c>), which becomes <see cref="PhpConstDeclListAst"/>.
        /// </summary>
        public override TyhpObjectShapeAst VisitTyhpObjectShape(
            [NotNull] TyhpParser.TyhpObjectShapeContext context)
        {
            var members = context.StatementList != null
                ? this.VisitTyhpObjectShapeStatementList(context.StatementList)
                : PhpClassBodyAst.Create(null, context, GetCurrentLanguageMode(context));

            return TyhpObjectShapeAst.Create(members, context, GetCurrentLanguageMode(context));
        }


        /// <summary>
        /// Visits an alias-RHS intersection that mixes nominal types with an object
        /// shape, e.g. <c>LoggerInterface &amp; object { … }</c>. Produces the same
        /// <see cref="PhpTypeKind.Intersection"/> wrapper as an ordinary
        /// <c>intersectionType</c>; each shape item is a <see cref="TyhpObjectShapeAst"/>
        /// (members retained), not builtin <c>object</c>.
        /// </summary>
        public override PhpTypeExpressionAst VisitTyhpObjectShapeIntersection(
            [NotNull] TyhpParser.TyhpObjectShapeIntersectionContext context)
            => PhpTypeExpressionAst.Create(
                PhpTypeExpressionListAst.Create(
                    context._Items.Select(this.VisitTyhpObjectShapeIntersectionItem),
                    context
                ),
                PhpTypeKind.Intersection,
                false,
                false,
                context
            );


        /// <summary>
        /// Visits one item of <see cref="VisitTyhpObjectShapeIntersection"/>: either a
        /// nominal type or an <c>object { … }</c> shape.
        /// </summary>
        public override ITypeExpression VisitTyhpObjectShapeIntersectionItem(
            [NotNull] TyhpParser.TyhpObjectShapeIntersectionItemContext context)
        {
            if (context.ObjectShape != null)
            {
                return this.VisitTyhpObjectShape(context.ObjectShape);
            }
            else if (context.NominalType != null)
            {
                return this.VisitType(context.NominalType);
            }
            else
            {
                this.ReportUnexpectedAlternative(context, "tyhpObjectShapeIntersectionItem");
                return ErrorAst.Create(context, GetCurrentLanguageMode(context));
            }
        }


        public IClassMember? VisitTyhpObjectShapeStatement(
            TyhpParser.TyhpObjectShapeStatementContext? context)
        {
            if (context == null)
            {
                return null;
            }

            return context switch
            {
                TyhpParser.TyhpObjectShapeClassConstsContext ctx =>
                    this.VisitTyhpObjectShapeClassConsts(ctx),
                TyhpParser.TyhpObjectShapeClassTypedConstsContext ctx =>
                    this.VisitTyhpObjectShapeClassTypedConsts(ctx),
                TyhpParser.TyhpObjectShapeTyhpdefMemberContext ctx =>
                    this.VisitTyhpObjectShapeTyhpdefMember(ctx),
                _ => HandleUnexpectedAlternative<IClassMember>(context, "tyhpObjectShapeStatement")
            };
        }


        /// <summary>
        /// Visits untyped <c>const NAME = expr</c> inside an object shape.
        /// </summary>
        public override PhpConstDeclListAst VisitTyhpObjectShapeClassConsts(
            [NotNull] TyhpParser.TyhpObjectShapeClassConstsContext context)
            => this.VisitObjectShapeClassConstList(
                context,
                context.Attributes,
                context.tyhpdefDeprecatedOrObsolete(),
                context.Modifiers,
                context.ConstList,
                type: null);


        /// <summary>
        /// Visits typed <c>const T NAME = expr</c> inside an object shape.
        /// </summary>
        public override PhpConstDeclListAst VisitTyhpObjectShapeClassTypedConsts(
            [NotNull] TyhpParser.TyhpObjectShapeClassTypedConstsContext context)
        {
            ITypeExpression? type = null;
            if (context.TypeExpr != null)
            {
                type = this.VisitTypeExprWithoutStatic(context.TypeExpr);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpObjectShapeClassTypedConsts.TypeExpr");
            }

            return this.VisitObjectShapeClassConstList(
                context,
                context.Attributes,
                context.tyhpdefDeprecatedOrObsolete(),
                context.Modifiers,
                context.ConstList,
                type);
        }


        /// <summary>
        /// Visits a non-PHP-const shape member by delegating to
        /// <see cref="VisitTyhpdefClassStatement"/>.
        /// </summary>
        public override IClassMember VisitTyhpObjectShapeTyhpdefMember(
            [NotNull] TyhpParser.TyhpObjectShapeTyhpdefMemberContext context)
        {
            if (context.Member == null)
            {
                this.ReportMissingRequired(context, "tyhpObjectShapeTyhpdefMember.Member");
                return ErrorAst.Create(context, GetCurrentLanguageMode(context));
            }

            return this.VisitTyhpdefClassStatement(context.Member)
                ?? ErrorAst.Create(context, GetCurrentLanguageMode(context));
        }


        /// <summary>
        /// Visits an object-shape body. PHP <c>const NAME = expr</c> / typed
        /// <c>const T NAME = expr</c> become <see cref="PhpConstDeclListAst"/> so
        /// shape assignability can see constants; every other member is a tyhpdef
        /// class statement.
        /// </summary>
        public override PhpClassBodyAst VisitTyhpObjectShapeStatementList(
            [NotNull] TyhpParser.TyhpObjectShapeStatementListContext context)
            => PhpClassBodyAst.Create(
                (context._Items ?? []).Where(item => item != null).Select(this.VisitTyhpObjectShapeStatement!),
                context
            );


        /// <summary>
        /// tyhpOptionalGenericIdentifier
        ///     : Identifier=identifier
        ///     | GenericIdentifier=tyhpGenericIdentifier {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override PhpNameAst VisitTyhpOptionalGenericIdentifier([NotNull] TyhpParser.TyhpOptionalGenericIdentifierContext context)
        {
            return context switch
            {
                _ when context.Identifier != null => this.VisitIdentifier(context.Identifier),
                _ when context.GenericIdentifier != null => this.VisitTyhpGenericIdentifier(context.GenericIdentifier),
                _ => HandleUnexpectedAlternativeSpecial(context, "tyhpOptionalGenericIdentifier",
                    () => PhpNameAst.CreateError(context, GetCurrentLanguageMode(context)))
            };
        }


        /// <summary>
        /// tyhpOptionalGenericIdentifierWithoutConstructor
        ///     : Identifier=identifierWithoutConstructor
        ///     | GenericIdentifier=tyhpGenericIdentifierWithoutConstructor {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override PhpNameAst VisitTyhpOptionalGenericIdentifierWithoutConstructor([NotNull] TyhpParser.TyhpOptionalGenericIdentifierWithoutConstructorContext context)
        {
            return context switch
            {
                _ when context.Identifier != null => this.VisitIdentifierWithoutConstructor(context.Identifier),
                _ when context.GenericIdentifier != null => this.VisitTyhpGenericIdentifierWithoutConstructor(context.GenericIdentifier),
                _ => HandleUnexpectedAlternativeSpecial(context, "tyhpOptionalGenericIdentifierWithoutConstructor",
                    () => PhpNameAst.CreateError(context, GetCurrentLanguageMode(context)))
            };
        }

        /// <summary>
        /// tyhpReservedNonModifiers
        ///     : TokenValue=T_TYHP_TYPE_ALIAS
        ///     | TokenValue=T_TYHP_AWAIT
        ///     | TokenValue=T_TYHP_WITH
        ///     | TokenValue=T_TYHP_OPERATOR
        ///     | TokenValue=T_TYHP_VOID
        ///     | TokenValue=T_TYHP_PARENT
        ///     | TokenValue=T_TYHP_EXTENSION
        ///     ;
        /// </summary>
        public override TokenValueAst VisitTyhpReservedNonModifiers([NotNull] TyhpParser.TyhpReservedNonModifiersContext context)
            => this.GetTokenValueAst(context, context.TokenValue);


        public ITypeExpression VisitTyhpScalarType([NotNull] TyhpParser.TyhpScalarTypeContext context)
        {
            return context switch
            {
                TyhpParser.ScalarTypeDoubleQuoteStringContext dq => TyhpTemplateStringTypeAst.Create(
                    dq.EncapsList != null
                        ? VisitEncapsList(dq.EncapsList)
                        : PhpEncapsListAst.Create([], dq),
                    dq,
                    GetCurrentLanguageMode(dq)),
                TyhpParser.ScalarTypeSingleQuoteStringContext sq => PhpBuiltinTypeAst.Create(
                    sq.Scalar?.Text ?? string.Empty,
                    sq,
                    GetCurrentLanguageMode(sq)),
                _ => PhpBuiltinTypeAst.Create(
                    ScalarTypeSpelling(context),
                    context,
                    GetCurrentLanguageMode(context)),
            };
        }


        /// <summary>
        /// tyhpSemiReserved
        ///     : TokenValue=T_TYHP_ASYNC
        ///     | TokenValue=T_TYHP_OPERATOR
        ///     | TokenValue=T_TYHPDEF_DEPRECATED
        ///     | TokenValue=T_TYHPDEF_OBSOLETE
        ///     | TokenValue=T_TYHP_IS
        ///     ;
        /// </summary>
        public override TokenValueAst VisitTyhpSemiReserved([NotNull] TyhpParser.TyhpSemiReservedContext context)
            => this.GetTokenValueAst(context, context.TokenValue);


        /// <summary>
        /// tyhpStringWithOptionalGeneric
        ///     : Identifier=T_STRING GenericArguments=tyhpGenericTypeArguments?
        ///     ;
        /// </summary>
        public override PhpNameAst VisitTyhpStringWithOptionalGeneric([NotNull] TyhpParser.TyhpStringWithOptionalGenericContext context)
        {
            if (context.GenericArguments != null)
            {
                return TyhpGenericIdentifierAst.Create(
                    context.Identifier,
                    this.VisitTyhpGenericTypeArguments(context.GenericArguments),
                    context);
            }

            return PhpNameAst.Create(context.Identifier, context);
        }


        /// <summary>
        /// Visits a single struct property declaration.
        ///
        /// Grammar:
        ///   tyhpStructProperty
        ///     : TypeExpr=typeExprWithoutStatic
        ///         ((AliasOfString=T_CONSTANT_ENCAPSED_STRING | AliasOfInt=T_LNUMBER) T_AS)?
        ///         Property=property T_SYM_SEMICOLON
        ///     ;
        /// </summary>
        public override TyhpStructPropertyAst VisitTyhpStructProperty([NotNull] TyhpParser.TyhpStructPropertyContext context)
        {
            string? aliasOf = null;
            var aliasIsNumeric = false;
            if (context.AliasOfString != null)
            {
                aliasOf = context.AliasOfString.Text;
            }
            else if (context.AliasOfInt != null)
            {
                aliasOf = context.AliasOfInt.Text;
                aliasIsNumeric = true;
            }

            return TyhpStructPropertyAst.Create(
                this.VisitTypeExprWithoutStatic(context.TypeExpr),
                this.VisitProperty(context.Property),
                aliasOf,
                aliasIsNumeric,
                context
            );
        }


        /// <summary>
        /// Visits a list of struct property declarations.
        ///
        /// Grammar:
        ///   tyhpStructPropertyList
        ///     : Items+=tyhpStructProperty*
        ///     ;
        /// </summary>
        public override TyhpStructPropertyListAst VisitTyhpStructPropertyList([NotNull] TyhpParser.TyhpStructPropertyListContext context)
            => TyhpStructPropertyListAst.Create(
                (context._Items ?? Enumerable.Empty<TyhpParser.TyhpStructPropertyContext>())
                    .Select(this.VisitTyhpStructProperty),
                context
            );


        /// <summary>
        /// Visits a type-position / alias-RHS <c>struct { … }</c> shape.
        /// </summary>
        public override TyhpStructShapeAst VisitTyhpStructShape(
            [NotNull] TyhpParser.TyhpStructShapeContext context)
        {
            TyhpStructPropertyListAst propertyList;
            if (context.PropertyList != null)
            {
                propertyList = this.VisitTyhpStructPropertyList(context.PropertyList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpStructShape.PropertyList");
                propertyList = TyhpStructPropertyListAst.Create(null, context);
            }

            return TyhpStructShapeAst.Create(
                propertyList,
                context.Extends != null ? this.VisitClassName(context.Extends) : null,
                context,
                GetCurrentLanguageMode(context));
        }

        /// <summary>
        /// Visits a Tyhp type alias declaration.
        ///
        /// Grammar:
        ///   tyhpTypeAlias
        ///     : T_TYHP_TYPE_ALIAS Identifier=name
        ///         GenericArguments=tyhpGenericParameterDeclarations? T_SYM_EQUAL
        ///         ( {this.looksLikeObjectShapeIntersection()}?
        ///             ObjectShapeIntersection=tyhpObjectShapeIntersection
        ///         | {this.looksLikeObjectShape()}? ObjectShape=tyhpObjectShape
        ///         | TypeExpr=typeExpr ) T_SYM_SEMICOLON
        ///     ;
        ///
        /// ANTLR recovery after truncated input (e.g. <c>type Foo</c> at EOF) can leave
        /// <c>Identifier</c> / <c>TypeExpr</c> / <c>ObjectShape</c> /
        /// <c>ObjectShapeIntersection</c> null — report
        /// <see cref="Domain.Exceptions.MessageCode.VisitorMissingRequiredNode"/> and use
        /// placeholders instead of throwing. Object-shape members become a
        /// <see cref="TyhpObjectShapeAst"/> attached as the alias type (or as an
        /// intersection item when the RHS is <c>Nominal &amp; object { … }</c>).
        /// </summary>
        public override TyhpTypeAliasAst VisitTyhpTypeAlias([NotNull] TyhpParser.TyhpTypeAliasContext context)
        {
            PhpNameAst name;
            if (context.Identifier != null)
            {
                name = this.VisitName(context.Identifier);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpTypeAlias.Identifier");
                name = PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var genericArgs = context.GenericArguments != null
                ? this.VisitTyhpGenericParameterDeclarations(context.GenericArguments)
                : null;

            ITypeExpression typeExpr;
            if (context.TypeExpr != null)
            {
                typeExpr = this.VisitTypeExpr(context.TypeExpr);
            }
            else if (context.ObjectShapeIntersection != null)
            {
                typeExpr = this.VisitTyhpObjectShapeIntersection(context.ObjectShapeIntersection);
            }
            else if (context.ObjectShape != null)
            {
                typeExpr = this.VisitTyhpObjectShape(context.ObjectShape);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpTypeAlias.TypeExpr");
                typeExpr = PhpTypeExpressionAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            return TyhpTypeAliasAst.Create(name, genericArgs, typeExpr, context);
        }


        /// <summary>
        /// Visit a typed variable declaration expression.
        ///
        /// Grammar (TyhpParser.g4):
        ///   tyhpTypedVarExpr
        ///       : TypeExpr=typeExprWithoutStatic Variable=simpleVariable
        ///           (FindDocCommentCheck=T_SYM_EQUAL IsRef=ampersand? EqualsExpr=expr)?
        ///       | T_OPEN_ROUND_BRACE TypeExpr=typeExprWithoutStatic T_CLOSE_ROUND_BRACE
        ///           Variable=simpleVariable
        ///           (FindDocCommentCheck=T_SYM_EQUAL IsRef=ampersand? EqualsExpr=expr)?
        ///       ;
        ///
        /// Examples:
        ///   int $x = 5;
        ///   string $name;
        ///   (int) $x = &amp;$other;
        /// </summary>
        public override TyhpTypedVarExprAst VisitTyhpTypedVarExpr(
            [NotNull] TyhpParser.TyhpTypedVarExprContext context)
        {
            var typeExpr = context.TypeExpr is not null
                ? this.VisitOptionalTypeWithoutStatic(context.TypeExpr)
                : null;

            PhpVariableAst variable;
            if (context.Variable != null)
            {
                variable = this.VisitSimpleVariable(context.Variable);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpTypedVarExpr.Variable");
                variable = PhpVariableAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var assignedExpr = context.EqualsExpr != null
                ? this.VisitExpr(context.EqualsExpr)
                : null;
            var isRef = context.IsRef != null;
            var isParenthesized = context.T_OPEN_ROUND_BRACE() != null;

            var docComment = context.FindDocCommentCheck != null
                ? this.FindPossibleDocComment(context.FindDocCommentCheck)
                : null;

            return TyhpTypedVarExprAst.Create(
                typeExpr,
                variable,
                assignedExpr,
                isRef,
                isParenthesized,
                context,
                docComment
            );
        }


        /// <summary>
        /// Visit a Tyhp using block statement.
        ///
        /// Grammar (TyhpParser.g4):
        ///   tyhpUsingBlock
        ///       : T_TYHP_USING IsAsync=T_TYHP_AWAIT?
        ///         T_OPEN_ROUND_BRACE Resources=tyhpUsingResourceList T_CLOSE_ROUND_BRACE
        ///         T_OPEN_CURLY_BRACE StatementList=innerStatementList T_CLOSE_CURLY_BRACE
        ///       ;
        /// </summary>
        public override TyhpUsingBlockAst VisitTyhpUsingBlock(
            [NotNull] TyhpParser.TyhpUsingBlockContext context)
        {
            var isAsync = context.IsAsync != null;
            var resources = context.Resources._Items
                .Select(r => VisitTyhpUsingResource(r))
                .ToList();
            var body = context.StatementList != null
                ? this.VisitInnerStatementList(context.StatementList)
                : null;

            return TyhpUsingBlockAst.Create(isAsync, resources, body, context, GetCurrentLanguageMode(context));
        }


        /// <summary>
        /// Visit an individual resource declaration within a using block.
        /// Pattern-matches on the labeled alternative subclass types generated
        /// by ANTLR for the tyhpUsingResource rule.
        /// </summary>
        private TyhpUsingResourceAst VisitTyhpUsingResource(
            [NotNull] TyhpParser.TyhpUsingResourceContext context)
        {
            return context switch
            {
                TyhpParser.TyhpUsingResourceTypedContext typed =>
                    TyhpUsingResourceAst.Create(
                        this.VisitTypeExprWithoutStatic(typed.TypeExpr),
                        this.VisitSimpleVariable(typed.Variable),
                        this.VisitExpr(typed.Expr) as IExpression
                            ?? throw new InvalidOperationException(
                                $"Using resource expression at {typed.Expr?.Start?.Line}:{typed.Expr?.Start?.Column} did not produce an IExpression"),
                        typed, GetCurrentLanguageMode(context)),

                TyhpParser.TyhpUsingResourceInferredContext inferred =>
                    TyhpUsingResourceAst.Create(
                        null,
                        this.VisitSimpleVariable(inferred.Variable),
                        this.VisitExpr(inferred.Expr) as IExpression
                            ?? throw new InvalidOperationException(
                                $"Using resource expression at {inferred.Expr?.Start?.Line}:{inferred.Expr?.Start?.Column} did not produce an IExpression"),
                        inferred, GetCurrentLanguageMode(context)),

                TyhpParser.TyhpUsingResourceUnassignedContext unassigned =>
                    TyhpUsingResourceAst.Create(
                        null, null,
                        this.VisitExpr(unassigned.Expr) as IExpression
                            ?? throw new InvalidOperationException(
                                $"Using resource expression at {unassigned.Expr?.Start?.Line}:{unassigned.Expr?.Start?.Column} did not produce an IExpression"),
                        unassigned, GetCurrentLanguageMode(context)),

                _ => throw new InvalidOperationException(
                    $"Unexpected TyhpUsingResource alternative: {context.GetType().Name}")
            };
        }

        private static void ReadTyhpdefDeclModifier(
            TokenValueAst? token,
            out bool isDeprecated,
            out bool isObsolete,
            out bool isOmit)
        {
            isDeprecated = token?.ValueInt64 == TyhpParser.T_TYHPDEF_DEPRECATED;
            isObsolete = token?.ValueInt64 == TyhpParser.T_TYHPDEF_OBSOLETE;
            isOmit = token?.ValueInt64 == TyhpParser.T_TYHPDEF_OMIT;
        }

        private void AttachOverlayAgainst(Base2Ast node, ParserRuleContext context)
        {
            // Class-member rules start at a leading `#[…]`, so a backward walk from
            // context.Start misses `// @overlay-against:` written after the attribute
            // and before the keyword (where `tyhp overlay stamp` inserts it). Prefer
            // that comment, then a stamp that precedes the attributes.
            var stamp = this.FindOverlayAgainstAfterLeadingAttributes(context);
            if (string.IsNullOrEmpty(stamp))
            {
                stamp = this.FindPossibleOverlayAgainst(context.Start);
            }

            if (!string.IsNullOrEmpty(stamp))
            {
                node.AddGrammarAddon(
                    "overlayAgainst",
                    TokenValueAst.Create(stamp, 0, context, GetCurrentLanguageMode(context)));
            }
        }

        /// <summary>
        /// Stamp comment in the token gap after a leading <c>attributes</c> child and
        /// before the next default-channel token (modifier, keyword, or type).
        /// </summary>
        private string? FindOverlayAgainstAfterLeadingAttributes(ParserRuleContext context)
        {
            if (context.ChildCount == 0
                || context.GetChild(0) is not TyhpParser.AttributesContext attributes
                || attributes.Stop == null
                || this._tokens == null)
            {
                return null;
            }

            var limit = context.Stop?.TokenIndex ?? attributes.Stop.TokenIndex;
            string? stamp = null;
            for (var i = attributes.Stop.TokenIndex + 1; i <= limit; i++)
            {
                var token = this._tokens.Get(i);
                if (token == null)
                {
                    break;
                }

                if (token.Channel == TyhpLexer.WhiteSpaceChannel
                    || token.Channel == TokenConstants.HiddenChannel
                    || token.Channel == TyhpLexer.DocBlockCommentsChannel)
                {
                    continue;
                }

                if (token.Channel == TyhpLexer.SimpleCommentsChannel)
                {
                    var extracted = ExtractOverlayAgainstStamp(token.Text);
                    if (extracted != null)
                    {
                        stamp = extracted;
                    }

                    continue;
                }

                break;
            }

            return stamp;
        }

        private void AttachPartialFunctionAlias(IBase2Ast nameOrAlias, IToken? aliasedAs, ParserRuleContext context)
        {
            if (aliasedAs == null || nameOrAlias is not Base2Ast nameNode)
            {
                return;
            }

            nameNode.AddGrammarAddon("aliasedAs", PhpNameAst.Create(aliasedAs, context));
        }

        private void AttachProvidedBy(Base2Ast node, ParserRuleContext context)
        {
            var package = this.FindPossibleProvidedBy(context.Start);
            if (!string.IsNullOrEmpty(package))
            {
                node.AddGrammarAddon(
                    TyhpdefImportObjectDeclAst.ProvidedByAddonKey,
                    TokenValueAst.Create(package, 0, context, GetCurrentLanguageMode(context)));
            }
        }

        /// <summary>
        /// Dispatches tyhpdefAttributedStatement labeled alternatives.
        /// Grammar: tyhpdefAttributedStatement
        ///   : Statement=tyhpdefExternClassDeclarationStatement              #tyhpdefExternClassDecl
        ///   | Statement=tyhpdefExternInterfaceDeclarationStatement          #tyhpdefExternInterfaceDecl
        ///   | Statement=tyhpdefExternEnumDeclarationStatement               #tyhpdefExternEnumDecl
        ///   | Statement=tyhpdefExternFunctionDeclarationStatement           #tyhpdefExternFunctionDecl
        ///   | Statement=tyhpdefExternConstDeclarationStatement              #tyhpdefExternConstDecl
        ///   | Statement=tyhpdefExternDeclarationStatement                   #tyhpdefExternDecl
        ///   | Statement=tyhpdefImportFunctionDeclarationStatement           #tyhpdefImportFunctionDecl
        ///   | Statement=tyhpdefImportClassDeclarationStatement              #tyhpdefImportClassDecl
        ///   | Statement=tyhpdefImportTraitDeclarationStatement              #tyhpdefImportTraitDecl
        ///   | Statement=tyhpdefImportInterfaceDeclarationStatement          #tyhpdefImportInterfaceDecl
        ///   | Statement=tyhpdefImportEnumDeclarationStatement               #tyhpdefImportEnumDecl
        /// </summary>
        public IAttributedStatement? VisitTyhpdefAttributedStatement(TyhpParser.TyhpdefAttributedStatementContext? context)
        {
            if (context == null)
            {
                return null;
            }

            return context switch
            {
                TyhpParser.TyhpdefExternClassDeclContext ctx => this.VisitTyhpdefExternClassDecl(ctx),
                TyhpParser.TyhpdefExternInterfaceDeclContext ctx => this.VisitTyhpdefExternInterfaceDecl(ctx),
                TyhpParser.TyhpdefExternEnumDeclContext ctx => this.VisitTyhpdefExternEnumDecl(ctx),
                TyhpParser.TyhpdefExternFunctionDeclContext ctx => this.VisitTyhpdefExternFunctionDecl(ctx),
                TyhpParser.TyhpdefExternConstDeclContext ctx => this.VisitTyhpdefExternConstDecl(ctx),
                TyhpParser.TyhpdefExternDeclContext ctx => this.VisitTyhpdefExternDecl(ctx),
                TyhpParser.TyhpdefPartialFunctionDeclContext ctx => this.VisitTyhpdefPartialFunctionDecl(ctx),
                TyhpParser.TyhpdefImportFunctionDeclContext ctx => this.VisitTyhpdefImportFunctionDecl(ctx),
                TyhpParser.TyhpdefImportClassDeclContext ctx => this.VisitTyhpdefImportClassDecl(ctx),
                TyhpParser.TyhpdefImportTraitDeclContext ctx => this.VisitTyhpdefImportTraitDecl(ctx),
                TyhpParser.TyhpdefImportInterfaceDeclContext ctx => this.VisitTyhpdefImportInterfaceDecl(ctx),
                TyhpParser.TyhpdefImportEnumDeclContext ctx => this.VisitTyhpdefImportEnumDecl(ctx),
                _ => HandleUnexpectedAlternative<IAttributedStatement>(context, "tyhpdefAttributedStatement")
            };
        }

        /// <summary>
        /// Visits a name-only overlay <c>partial function</c> method (attributes only; no signature).
        /// Grammar: Attributes=attributes? T_TYHPDEF_PARTIAL function
        ///   Identifier=tyhpdefPartialFunctionName T_SYM_SEMICOLON
        /// </summary>
        public override PhpMethodDeclAst VisitTyhpdefPartialClassMethod(
            [NotNull] TyhpParser.TyhpdefPartialClassMethodContext context)
        {
            IBase2Ast nameOrAlias;
            if (context.Identifier != null)
            {
                nameOrAlias = this.VisitTyhpdefPartialFunctionName(context.Identifier);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefPartialClassMethod.Identifier");
                nameOrAlias = PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var methodName = !string.IsNullOrEmpty(nameOrAlias.Identifier)
                ? nameOrAlias.Identifier
                : (nameOrAlias.ValueString ?? "");

            var result = PhpMethodDeclAst.Create(
                methodName,
                returnsRef: false,
                modifiers: null,
                parameters: null,
                returnType: null,
                body: null,
                docComment: null,
                context,
                GetCurrentLanguageMode(context),
                isPartial: true);
            this.AttachPartialFunctionAlias(nameOrAlias, context.AliasedAs, context);
            this.AttachOverlayAgainst(result, context);
            result.AddGrammarAddon("nameOrAlias", nameOrAlias);

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Visits a tyhpdef import class method.
        /// Grammar: tyhpdefDeprecatedOrObsolete? IsAsync=T_TYHP_ASYNC? Modifiers=methodModifiers function
        ///   ReturnsRef=returnsRef Identifier=tyhpdefFunctionNameWithOptionalAlias
        ///   FindDocComment=T_OPEN_ROUND_BRACE ParameterList=parameterList
        ///   T_CLOSE_ROUND_BRACE ReturnType=returnType T_SYM_SEMICOLON
        /// </summary>
        public override PhpMethodDeclAst VisitTyhpdefImportClassMethod([NotNull] TyhpParser.TyhpdefImportClassMethodContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var docComment = context.FindDocComment != null
                ? this.FindPossibleDocComment(context.FindDocComment)
                : null;

            IBase2Ast nameOrAlias;
            if (context.Identifier != null)
            {
                nameOrAlias = this.VisitTyhpdefFunctionNameWithOptionalAlias(context.Identifier);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefImportClassMethod.Identifier");
                nameOrAlias = PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            // Name AST nodes such as PhpNameAst carry the method name in ValueString, while the
            // Base2Ast.Identifier property defaults to "" (never null). A plain `Identifier ?? ValueString`
            // therefore always yields the empty string, leaving the method unnamed (and unresolvable as a
            // member). Prefer Identifier only when non-empty, otherwise fall back to ValueString.
            var methodName = !string.IsNullOrEmpty(nameOrAlias.Identifier)
                ? nameOrAlias.Identifier
                : (nameOrAlias.ValueString ?? "");

            var isOmit = deprecatedOrObsolete?.ValueInt64 == TyhpParser.T_TYHPDEF_OMIT;
            var result = PhpMethodDeclAst.Create(
                methodName,
                context.ReturnsRef != null && this.VisitReturnsRef(context.ReturnsRef) != null,
                context.Modifiers != null ? this.VisitMethodModifiers(context.Modifiers) : null,
                context.ParameterList != null ? this.VisitParameterList(context.ParameterList) : null,
                context.ReturnType != null ? this.VisitReturnType(context.ReturnType) : null,
                null, // no body in tyhpdef
                docComment,
                context,
                GetCurrentLanguageMode(context),
                isOmit: isOmit
            );
            this.AttachOverlayAgainst(result, context);

            result.AddGrammarAddon("nameOrAlias", nameOrAlias);

            // Method-level generic parameters (e.g. `function with<T, U>(...)`) are attached to the
            // name AST under "GenericArguments". Re-expose them under "identifier" so the shared
            // method binder (PopulateGenericParametersFromGrammarAddon) registers them.
            if (nameOrAlias.AstGrammarAddons.TryGetValue("GenericArguments", out var methodGenerics))
            {
                result.AddGrammarAddon("identifier", methodGenerics);
            }

            if (context.IsAsync != null)
            {
                result.AddGrammarAddon("isAsync", TokenValueAst.Create("async", TyhpParser.T_TYHP_ASYNC, context));
            }
            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Visits <c>use extension</c> inside a tyhpdef class body.
        /// Grammar: tyhpdefDeprecatedOrObsolete? T_USE T_TYHP_EXTENSION UseDecl=useDeclarations
        ///   Adaptations=traitAdaptations   #tyhpdefClassUseExtension
        /// </summary>
        public override TyhpImportExtensionAst VisitTyhpdefClassUseExtension([NotNull] TyhpParser.TyhpdefClassUseExtensionContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            PhpImportDeclListAst useDeclarations;
            if (context.UseDecl != null)
            {
                useDeclarations = this.VisitUseDeclarations(context.UseDecl);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefClassUseExtension.UseDecl");
                useDeclarations = PhpImportDeclListAst.Create(null, context, GetCurrentLanguageMode(context));
            }

            PhpTraitAdaptationListAst? adaptations = null;
            if (context.Adaptations != null)
            {
                adaptations = this.VisitTraitAdaptations(context.Adaptations);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefClassUseExtension.Adaptations");
            }

            var result = TyhpImportExtensionAst.Create(
                useDeclarations,
                adaptations,
                context,
                GetCurrentLanguageMode(context));

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            return result;
        }

        /// <summary>
        /// Visits a tyhpdef enum case.
        /// Grammar: tyhpdefDeprecatedOrObsolete? EnumCase=enumCase
        /// </summary>
        public override PhpEnumCaseAst VisitTyhpdefEnumCase([NotNull] TyhpParser.TyhpdefEnumCaseContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var result = this.VisitEnumCase(context.EnumCase);
            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Visits a tyhpdef trait use.
        /// Grammar: tyhpdefDeprecatedOrObsolete? T_USE TraitNameList=classNameList
        ///   Adaptations=traitAdaptations
        /// </summary>
        public override PhpTraitUseAst VisitTyhpdefTraitUse([NotNull] TyhpParser.TyhpdefTraitUseContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            PhpClassNameListAst? traitNames;
            if (context.TraitNameList != null)
            {
                traitNames = this.VisitClassNameList(context.TraitNameList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefTraitUse.TraitNameList");
                traitNames = PhpClassNameListAst.Create(null, context);
            }

            PhpTraitAdaptationListAst? adaptations = null;
            if (context.Adaptations != null)
            {
                adaptations = this.VisitTraitAdaptations(context.Adaptations);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefTraitUse.Adaptations");
            }

            var result = PhpTraitUseAst.Create(
                traitNames,
                adaptations,
                context,
                GetCurrentLanguageMode(context)
            );

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }
            return result;
        }

        /// <summary>
        /// Visits a tyhpdef class operator overload.
        /// Grammar: tyhpdefClassOperator T_SYM_SEMICOLON   #tyhpdefClassOperatorDecl
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpdefClassOperatorDecl([NotNull] TyhpParser.TyhpdefClassOperatorDeclContext context)
        {
            var languageMode = GetCurrentLanguageMode(context);
            var opCtx = context.tyhpdefClassOperator();
            if (opCtx == null)
            {
                this.ReportMissingRequired(context, "tyhpdefClassOperatorDecl.tyhpdefClassOperator");
                return TyhpOperatorOverloadAst.CreateError(context, languageMode);
            }

            TokenValueAst op;
            if (opCtx.Op != null)
            {
                op = this.VisitTyhpClassOperatorOverloadOp(opCtx.Op);
            }
            else
            {
                this.ReportMissingRequired(opCtx, "tyhpdefClassOperator.Op");
                op = TokenValueAst.CreateError(context, languageMode);
            }

            PhpParameterAst leftParam;
            if (opCtx.LeftParameter != null)
            {
                leftParam = this.VisitAttributedParameter(opCtx.LeftParameter);
            }
            else
            {
                this.ReportMissingRequired(opCtx, "tyhpdefClassOperator.LeftParameter");
                leftParam = this.CreateErrorParameter(context, languageMode);
            }

            var rightParam = opCtx.RightParameter != null
                ? this.VisitAttributedParameter(opCtx.RightParameter)
                : null;

            ITypeExpression? returnType = null;
            if (opCtx.ConvertReturnType != null)
            {
                returnType = this.VisitReturnType(opCtx.ConvertReturnType);
            }
            else
            {
                this.ReportMissingRequired(opCtx, "tyhpdefClassOperator.ConvertReturnType");
            }

            return TyhpOperatorOverloadAst.Create(
                op, leftParam, rightParam, returnType, null, null,
                context, languageMode
            );
        }

        /// <summary>
        /// Visits a tyhpdef class property declaration.
        /// Grammar: tyhpdefDeprecatedOrObsolete? Modifiers=propertyModifiers
        ///   TypeExpr=typeExprWithoutStatic PropertyList=tyhpdefPropertyList T_SYM_SEMICOLON
        /// Each tyhpdefProperty may take optional (T_COALESCE CoalesceExpr=expr).
        /// </summary>
        public override PhpPropertyDeclAst VisitTyhpdefClassProperty([NotNull] TyhpParser.TyhpdefClassPropertyContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            ITypeExpression typeExpr;
            if (context.TypeExpr != null)
            {
                typeExpr = this.VisitTypeExprWithoutStatic(context.TypeExpr);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefClassProperty.TypeExpr");
                typeExpr = ErrorAst.Create(context, GetCurrentLanguageMode(context));
            }

            var propertyList = context.PropertyList != null
                ? this.VisitTyhpdefPropertyList(context.PropertyList)
                : TyhpdefPropertyListAst.Create(null, context);

            var languageMode = GetCurrentLanguageMode(context);
            var result = PhpPropertyDeclAst.Create(
                context.Modifiers != null ? this.VisitPropertyModifiers(context.Modifiers) : null,
                typeExpr,
                // Wrap tyhpdef property list as PhpPropertyListAst for compatibility.
                // CoalesceExpr (?? expected default) maps onto PhpPropertyAst.DefaultValue
                // the same way PHP `= expr` does, so binder/IDE already see it.
                PhpPropertyListAst.Create(
                    propertyList.GetAllNotNull()
                        .Select(p => PhpPropertyAst.Create(
                            p.VariableName,
                            p.CoalesceExpr,
                            null,
                            null,
                            context,
                            languageMode)),
                    context
                ),
                context,
                languageMode
            );

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Visits a tyhpdef hooked class property (<c>#tyhpdefClassPropertyAccessors</c>).
        /// Mirrors <see cref="PhpParserAstVisitor.VisitClassPropertyAccessors"/>: one
        /// <see cref="PhpPropertyAst"/> whose <see cref="PhpPropertyAst.Hooks"/> is a
        /// <see cref="PhpPropertyHookListAst"/>. Each hook is bodyless
        /// (<c>PhpPropertyHookAst.Create(..., body: null, ...)</c>), matching PHP interface <c>get;</c>.
        /// </summary>
        public override PhpPropertyDeclAst VisitTyhpdefClassPropertyAccessors([NotNull] TyhpParser.TyhpdefClassPropertyAccessorsContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            ITypeExpression typeExpr;
            if (context.TypeExpr != null)
            {
                typeExpr = this.VisitTypeExprWithoutStatic(context.TypeExpr);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefClassPropertyAccessors.TypeExpr");
                typeExpr = ErrorAst.Create(context, GetCurrentLanguageMode(context));
            }

            PhpPropertyAst hookedProperty;
            if (context.PropertyAccessors != null)
            {
                hookedProperty = this.VisitTyhpdefHookedProperty(context.PropertyAccessors);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefClassPropertyAccessors.PropertyAccessors");
                hookedProperty = PhpPropertyAst.Create("<error>", null, null, null, context, GetCurrentLanguageMode(context));
            }

            var result = PhpPropertyDeclAst.Create(
                context.Modifiers != null ? this.VisitPropertyModifiers(context.Modifiers) : null,
                typeExpr,
                PhpPropertyListAst.Create([hookedProperty], context),
                context,
                GetCurrentLanguageMode(context)
            );

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Visits <c>tyhpdefHookedProperty</c>: one <c>$name</c>, optional <c>?? expr</c>
        /// expected default, plus a bodyless hook list.
        /// </summary>
        public override PhpPropertyAst VisitTyhpdefHookedProperty([NotNull] TyhpParser.TyhpdefHookedPropertyContext context)
        {
            var variableName = context.Variable?.Text;
            if (string.IsNullOrEmpty(variableName))
            {
                this.ReportMissingRequired(context, "tyhpdefHookedProperty.Variable");
                variableName = "<error>";
            }

            PhpPropertyHookListAst? hooks = null;
            if (context.Accessors != null)
            {
                hooks = this.VisitTyhpdefPropertyHookList(context.Accessors);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefHookedProperty.Accessors");
            }

            var coalesceExpr = context.CoalesceExpr != null
                ? this.VisitExpr(context.CoalesceExpr)
                : null;

            return PhpPropertyAst.Create(
                variableName,
                coalesceExpr,
                hooks,
                null,
                context,
                GetCurrentLanguageMode(context)
            );
        }

        /// <summary>
        /// Visits <c>tyhpdefPropertyHookList</c>, matching <see cref="PhpParserAstVisitor.VisitPropertyHookList"/>.
        /// </summary>
        public override PhpPropertyHookListAst VisitTyhpdefPropertyHookList([NotNull] TyhpParser.TyhpdefPropertyHookListContext context)
            => PhpPropertyHookListAst.Create(
                context._Items.Select(this.VisitTyhpdefPropertyHook),
                context
            );

        /// <summary>
        /// Visits a bodyless tyhpdef property hook (<c>get;</c> / <c>&amp;get;</c> / <c>set;</c>).
        /// Mirrors PHP interface <c>get;</c>: <c>body: null</c>, <c>ReturnsRef</c> from <c>returnsRef</c>,
        /// modifiers and attributes attached the same way as <see cref="PhpParserAstVisitor.VisitPropertyHook"/>.
        /// </summary>
        public override PhpPropertyHookAst VisitTyhpdefPropertyHook([NotNull] TyhpParser.TyhpdefPropertyHookContext context)
        {
            string? hookName = null;
            if (context.Identifier != null)
            {
                hookName = this.VisitIdentifier(context.Identifier).ValueString;
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefPropertyHook.Identifier");
            }

            return PhpPropertyHookAst.Create(
                hookName,
                context.ReturnsRef != null && this.VisitReturnsRef(context.ReturnsRef) != null,
                context.Modifiers != null ? this.VisitPropertyHookModifiers(context.Modifiers) : null,
                parameters: null,
                body: null,
                context,
                languageMode: GetCurrentLanguageMode(context),
                isExpressionBody: false
            ).WithAttributes(context.Attributes != null ? this.VisitAttributes(context.Attributes) : null);
        }

        /// <summary>
        /// Brace form yields a class body (empty when the statement list is missing).
        /// Semicolon overlay header form yields <c>null</c> so the AST is header-only.
        /// </summary>
        private PhpClassBodyAst? VisitTyhpdefObjectBodyOrHeaderOnly(
            TyhpParser.TyhpdefClassStatementListContext? statementList,
            ITerminalNode? semicolon,
            ParserRuleContext context)
        {
            if (semicolon != null)
            {
                return null;
            }

            return statementList != null
                ? this.VisitTyhpdefClassStatementList(statementList)
                : PhpClassBodyAst.Create(null, context);
        }

        /// <summary>
        /// Visits a tyhpdef class statement list.
        /// Grammar: tyhpdefClassStatementList
        ///   : Items+=tyhpdefClassStatement*
        /// </summary>
        public override PhpClassBodyAst VisitTyhpdefClassStatementList([NotNull] TyhpParser.TyhpdefClassStatementListContext context)
            => PhpClassBodyAst.Create(
                (context._Items ?? []).Where(item => item != null).Select(this.VisitTyhpdefClassStatement!),
                context
            );

        /// <summary>
        /// Dispatches tyhpdefClassStatement labeled alternatives.
        /// </summary>
        public IClassMember? VisitTyhpdefClassStatement(TyhpParser.TyhpdefClassStatementContext? context)
        {
            if (context == null)
            {
                return null;
            }

            return context switch
            {
                TyhpParser.TyhpdefClassPropertyContext ctx => this.VisitTyhpdefClassProperty(ctx),
                TyhpParser.TyhpdefClassPropertyAccessorsContext ctx => this.VisitTyhpdefClassPropertyAccessors(ctx),
                TyhpParser.TyhpdefImportClassConstContext ctx => this.VisitTyhpdefImportClassConst(ctx),
                TyhpParser.TyhpdefPartialClassMethodContext ctx => this.VisitTyhpdefPartialClassMethod(ctx),
                TyhpParser.TyhpdefImportClassMethodContext ctx => this.VisitTyhpdefImportClassMethod(ctx),
                TyhpParser.TyhpdefEnumCaseContext ctx => this.VisitTyhpdefEnumCase(ctx),
                TyhpParser.TyhpdefTraitUseContext ctx => this.VisitTyhpdefTraitUse(ctx),
                TyhpParser.TyhpdefClassUseExtensionContext ctx => this.VisitTyhpdefClassUseExtension(ctx),
                TyhpParser.TyhpdefExtensionFunctionDeclContext ctx => this.VisitTyhpdefExtensionFunctionDecl(ctx),
                TyhpParser.TyhpdefExtensionOperatorDeclContext ctx => this.VisitTyhpdefExtensionOperatorDecl(ctx),
                TyhpParser.TyhpdefClassOperatorDeclContext ctx => this.VisitTyhpdefClassOperatorDecl(ctx),
                TyhpParser.TyhpdefClassTypeAliasContext ctx => this.VisitTyhpdefClassTypeAlias(ctx),
                _ => HandleUnexpectedAlternative<IClassMember>(context, "tyhpdefClassStatement")
            };
        }

        /// <summary>
        /// Visits a class-body type alias in tyhpdef
        /// (<c>public type Name = …;</c>).
        /// </summary>
        public override TyhpTypeAliasAst VisitTyhpdefClassTypeAlias(
            [NotNull] TyhpParser.TyhpdefClassTypeAliasContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var modifiers = context.Modifier != null
                ? this.VisitNonEmptyMemberModifiers(context.Modifier)
                : null;

            if (context.TypeAlias is null)
            {
                this.ReportMissingRequired(context, "tyhpdefClassTypeAlias.TypeAlias");
                return TyhpTypeAliasAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var typeAlias = this.VisitTyhpTypeAlias(context.TypeAlias);
            var result = TyhpTypeAliasAst.Create(
                typeAlias.Name ?? PhpNameAst.CreateError(context, GetCurrentLanguageMode(context)),
                typeAlias.GenericArguments,
                typeAlias.TypeExpression
                    ?? PhpTypeExpressionAst.CreateError(context, GetCurrentLanguageMode(context)),
                context,
                modifiers);
            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Visits a tyhpdef deprecated, obsolete, or omit marker.
        /// Grammar: tyhpdefDeprecatedOrObsolete
        ///   : TokenValue=(T_TYHPDEF_DEPRECATED|T_TYHPDEF_OBSOLETE|T_TYHPDEF_OMIT)
        /// </summary>
        public override TokenValueAst VisitTyhpdefDeprecatedOrObsolete([NotNull] TyhpParser.TyhpdefDeprecatedOrObsoleteContext context)
            => this.GetTokenValueAst(context, context.TokenValue);

        //#endregion Identifier Visitors

        //#region Malformed-input recovery helpers

        /// <summary>
        /// Reports <see cref="MessageCode.VisitorMissingRequiredNode"/> for a child that ANTLR
        /// error recovery left null, so callers can continue with a placeholder AST instead of NRE.
        /// </summary>
        private void ReportMissingRequired(ParserRuleContext context, string ruleName)
        {
            this.Diagnostics.AddError(
                MessageCode.VisitorMissingRequiredNode,
                this._filename,
                context.Start?.Line ?? 0,
                context.Start?.Column ?? 0,
                ruleName);
        }

        /// <summary>
        /// Reports a missing required child and returns an <see cref="ErrorAst"/> usable wherever
        /// the visitor's interfaces (<see cref="ITopStatement"/>, <see cref="IAttributedStatement"/>, …)
        /// accept error recovery nodes.
        /// </summary>
        private ErrorAst ReportMissingRequiredAsErrorAst(ParserRuleContext context, string ruleName)
        {
            this.ReportMissingRequired(context, ruleName);
            return ErrorAst.Create(context, GetCurrentLanguageMode(context));
        }

        private PhpParameterAst CreateErrorParameter(ParserRuleContext context, string? languageMode)
            => PhpParameterAst.Create(
                "<error>",
                null,
                false,
                false,
                null,
                null,
                null,
                context,
                languageMode);

        private TyhpdefImportObjectDeclAst CreateErrorImportObjectDecl(ParserRuleContext context, string declKind)
        {
            var tokenType = declKind switch
            {
                "trait" => TyhpParser.T_TRAIT,
                "interface" => TyhpParser.T_INTERFACE,
                "enum" => TyhpParser.T_ENUM,
                "extern" => TyhpParser.T_TYHPDEF_EXTERN,
                _ => TyhpParser.T_CLASS,
            };

            return TyhpdefImportObjectDeclAst.Create(
                TokenValueAst.Create(declKind, tokenType, context),
                null,
                PhpNameAst.CreateError(context, GetCurrentLanguageMode(context)),
                null,
                null,
                null,
                PhpClassBodyAst.Create(null, context),
                false,
                false,
                null,
                context,
                GetCurrentLanguageMode(context));
        }

        /// <summary>
        /// Visits a tyhpdef class-body thin extension function (<c>extension fn … =&gt; expr;</c>).
        /// Grammar: tyhpdefDeprecatedOrObsolete? tyhpdefExtensionFunction #tyhpdefExtensionFunctionDecl
        /// </summary>
        public override TyhpdefInlineExtensionFunctionAst VisitTyhpdefExtensionFunctionDecl(
            [NotNull] TyhpParser.TyhpdefExtensionFunctionDeclContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var languageMode = GetCurrentLanguageMode(context);
            var fx = context.tyhpdefExtensionFunction();
            PhpMethodDeclAst inner;
            if (fx == null)
            {
                this.ReportMissingRequired(context, "tyhpdefExtensionFunctionDecl.tyhpdefExtensionFunction");
                inner = PhpMethodDeclAst.CreateError(context, languageMode);
            }
            else
            {
                inner = fx switch
                {
                    TyhpParser.TyhpdefExtensionFunctionShortDeclContext shortDecl
                        => this.BuildTyhpdefExtensionFunctionFromShort(shortDecl, context, languageMode),
                    _ => this.HandleUnexpectedAlternativeSpecial(
                        fx,
                        "tyhpdefExtensionFunction",
                        () => PhpMethodDeclAst.CreateError(context, languageMode)),
                };
            }

            var result = TyhpdefInlineExtensionFunctionAst.Create(inner, context, languageMode);

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                var attributes = this.VisitAttributes(context.Attributes);
                result.AddAttributes(attributes);
                inner.AddAttributes(attributes);
            }

            return result;
        }

        /// <summary>
        /// Do not call directly — use <see cref="VisitTyhpdefExtensionFunctionDecl"/> which handles
        /// <c>tyhpdefDeprecatedOrObsolete</c>. This override exists only to prevent ANTLR's default
        /// <c>VisitChildren</c> from running if the method is reached unexpectedly.
        /// </summary>
        public override TyhpdefInlineExtensionFunctionAst VisitTyhpdefExtensionFunctionShortDecl(
            [NotNull] TyhpParser.TyhpdefExtensionFunctionShortDeclContext context)
        {
            var languageMode = GetCurrentLanguageMode(context);
            var inner = this.BuildTyhpdefExtensionFunctionFromShort(context, context, languageMode);
            return TyhpdefInlineExtensionFunctionAst.Create(inner, context, languageMode);
        }

        /// <summary>
        /// Visits a tyhpdef inline extension operator.
        /// Grammar: tyhpdefDeprecatedOrObsolete? tyhpdefExtensionOperator #tyhpdefExtensionOperatorDecl
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpdefExtensionOperatorDecl(
            [NotNull] TyhpParser.TyhpdefExtensionOperatorDeclContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var languageMode = GetCurrentLanguageMode(context);
            var opCtx = context.tyhpdefExtensionOperator();
            TyhpOperatorOverloadAst result;
            if (opCtx == null)
            {
                this.ReportMissingRequired(context, "tyhpdefExtensionOperatorDecl.tyhpdefExtensionOperator");
                result = TyhpOperatorOverloadAst.CreateError(context, languageMode);
                result.IsInlineExtension = true;
            }
            else
            {
                result = opCtx switch
                {
                    TyhpParser.TyhpdefExtensionOperatorFullDeclContext fullOp =>
                        this.BuildTyhpdefExtensionOperatorFromFull(fullOp, context, languageMode),
                    TyhpParser.TyhpdefExtensionOperatorSignatureDeclContext sigOp =>
                        this.BuildTyhpdefExtensionOperatorFromSignature(sigOp, context, languageMode),
                    _ => this.HandleUnexpectedAlternativeSpecial(
                        opCtx,
                        "tyhpdefExtensionOperator",
                        () =>
                        {
                            var placeholder = TyhpOperatorOverloadAst.CreateError(context, languageMode);
                            placeholder.IsInlineExtension = true;
                            return placeholder;
                        }),
                };
            }

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        /// <summary>
        /// Do not call directly — use <see cref="VisitTyhpdefExtensionOperatorDecl"/>.
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpdefExtensionOperatorSignatureDecl(
            [NotNull] TyhpParser.TyhpdefExtensionOperatorSignatureDeclContext context)
            => this.BuildTyhpdefExtensionOperatorFromSignature(context, context, GetCurrentLanguageMode(context));

        /// <summary>
        /// Do not call directly — use <see cref="VisitTyhpdefExtensionOperatorDecl"/> which handles
        /// <c>tyhpdefDeprecatedOrObsolete</c>. This override exists only to prevent ANTLR's default
        /// <c>VisitChildren</c> from running if the method is reached unexpectedly.
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpdefExtensionOperatorFullDecl(
            [NotNull] TyhpParser.TyhpdefExtensionOperatorFullDeclContext context)
            => this.BuildTyhpdefExtensionOperatorFromFull(context, context, GetCurrentLanguageMode(context));

        private PhpMethodDeclAst BuildTyhpdefExtensionFunctionFromShort(
            TyhpParser.TyhpdefExtensionFunctionShortDeclContext shortDecl,
            ParserRuleContext context,
            string? languageMode)
        {
            var docComment = this.FindPossibleDocComment(shortDecl.FindDocComment);

            PhpNameAst nameAst;
            if (shortDecl.GenericIdentifier != null)
            {
                nameAst = this.VisitTyhpOptionalGenericIdentifierWithoutConstructor(shortDecl.GenericIdentifier);
            }
            else
            {
                this.ReportMissingRequired(shortDecl, "tyhpdefExtensionFunctionShortDecl.GenericIdentifier");
                nameAst = PhpNameAst.CreateError(context, languageMode);
            }

            var genericArgs = (nameAst as TyhpGenericIdentifierAst)?.GenericArguments;

            PhpParameterListAst? parameters;
            if (shortDecl.ParameterList != null)
            {
                parameters = this.VisitParameterList(shortDecl.ParameterList);
            }
            else
            {
                this.ReportMissingRequired(shortDecl, "tyhpdefExtensionFunctionShortDecl.ParameterList");
                parameters = PhpParameterListAst.Create([], context, languageMode);
            }

            ITypeExpression? returnType = null;
            if (shortDecl.ReturnType != null)
            {
                returnType = this.VisitReturnType(shortDecl.ReturnType);
            }
            else
            {
                this.ReportMissingRequired(shortDecl, "tyhpdefExtensionFunctionShortDecl.ReturnType");
            }

            IExpression expr;
            if (shortDecl.Expr != null)
            {
                expr = this.VisitExpr(shortDecl.Expr);
            }
            else
            {
                this.ReportMissingRequired(shortDecl, "tyhpdefExtensionFunctionShortDecl.Expr");
                expr = ErrorAst.Create(context, languageMode);
            }

            var body = PhpStatementBlockAst.Create(
                [PhpUnaryOpAst.Create(
                    TokenValueAst.Create("return", TyhpParser.T_RETURN, context),
                    expr,
                    context,
                    languageMode
                )],
                context,
                languageMode
            );

            return PhpMethodDeclAst.Create(
                    nameAst.ValueString ?? "",
                    shortDecl.ReturnsRef != null && this.VisitReturnsRef(shortDecl.ReturnsRef) != null,
                    null,
                    parameters,
                    returnType,
                    body,
                    docComment,
                    context,
                    languageMode,
                    isShortSyntax: true)
                .WithGrammarAddon("identifier", genericArgs);
        }

        private TyhpOperatorOverloadAst BuildTyhpdefExtensionOperatorFromFull(
            TyhpParser.TyhpdefExtensionOperatorFullDeclContext fullOp,
            ParserRuleContext context,
            string? languageMode)
        {
            TokenValueAst op;
            if (fullOp.Op != null)
            {
                op = this.VisitTyhpClassOperatorOverloadOp(fullOp.Op);
            }
            else
            {
                this.ReportMissingRequired(fullOp, "tyhpdefExtensionOperatorFullDecl.Op");
                op = TokenValueAst.CreateError(context, languageMode);
            }

            PhpParameterAst leftParam;
            if (fullOp.LeftParameter != null)
            {
                leftParam = this.VisitAttributedParameter(fullOp.LeftParameter);
            }
            else
            {
                this.ReportMissingRequired(fullOp, "tyhpdefExtensionOperatorFullDecl.LeftParameter");
                leftParam = this.CreateErrorParameter(context, languageMode);
            }

            var rightParam = fullOp.RightParameter != null
                ? this.VisitAttributedParameter(fullOp.RightParameter)
                : null;

            ITypeExpression? returnType = null;
            if (fullOp.ConvertReturnType != null)
            {
                returnType = this.VisitReturnType(fullOp.ConvertReturnType);
            }
            else
            {
                this.ReportMissingRequired(fullOp, "tyhpdefExtensionOperatorFullDecl.ConvertReturnType");
            }

            PhpStatementBlockAst? body;
            if (fullOp.Expr != null)
            {
                var expr = this.VisitExpr(fullOp.Expr);
                body = PhpStatementBlockAst.Create(
                    [PhpUnaryOpAst.Create(
                        TokenValueAst.Create("return", TyhpParser.T_RETURN, context),
                        expr,
                        context,
                        languageMode
                    )],
                    context,
                    languageMode
                );
            }
            else
            {
                this.ReportMissingRequired(fullOp, "tyhpdefExtensionOperatorFullDecl.Expr");
                body = null;
            }

            var result = TyhpOperatorOverloadAst.Create(
                op,
                leftParam,
                rightParam,
                returnType,
                body,
                null,
                context,
                languageMode,
                isShortSyntax: true);

            result.IsInlineExtension = true;
            return result;
        }

        private TyhpOperatorOverloadAst BuildTyhpdefExtensionOperatorFromSignature(
            TyhpParser.TyhpdefExtensionOperatorSignatureDeclContext sigOp,
            ParserRuleContext context,
            string? languageMode)
        {
            TokenValueAst op;
            if (sigOp.Op != null)
            {
                op = this.VisitTyhpClassOperatorOverloadOp(sigOp.Op);
            }
            else
            {
                this.ReportMissingRequired(sigOp, "tyhpdefExtensionOperatorSignatureDecl.Op");
                op = TokenValueAst.CreateError(context, languageMode);
            }

            PhpParameterAst leftParam;
            if (sigOp.LeftParameter != null)
            {
                leftParam = this.VisitAttributedParameter(sigOp.LeftParameter);
            }
            else
            {
                this.ReportMissingRequired(sigOp, "tyhpdefExtensionOperatorSignatureDecl.LeftParameter");
                leftParam = this.CreateErrorParameter(context, languageMode);
            }

            var rightParam = sigOp.RightParameter != null
                ? this.VisitAttributedParameter(sigOp.RightParameter)
                : null;

            ITypeExpression? returnType = null;
            if (sigOp.ConvertReturnType != null)
            {
                returnType = this.VisitReturnType(sigOp.ConvertReturnType);
            }
            else
            {
                this.ReportMissingRequired(sigOp, "tyhpdefExtensionOperatorSignatureDecl.ConvertReturnType");
            }

            var result = TyhpOperatorOverloadAst.Create(
                op,
                leftParam,
                rightParam,
                returnType,
                null,
                null,
                context,
                languageMode);

            result.IsInlineExtension = true;
            return result;
        }

