        /// <summary>
        /// Dispatches to name-only overlay <c>partial function</c>.
        /// Grammar: Statement=tyhpdefPartialFunctionDeclarationStatement   #tyhpdefPartialFunctionDecl
        /// </summary>
        public override TyhpdefImportFunctionDeclAst VisitTyhpdefPartialFunctionDecl([NotNull] TyhpParser.TyhpdefPartialFunctionDeclContext context)
        {
            if (context.Statement == null)
            {
                this.ReportMissingRequired(context, "tyhpdefPartialFunctionDecl.Statement");
                return TyhpdefImportFunctionDeclAst.Create(
                    PhpNameAst.CreateError(context, GetCurrentLanguageMode(context)),
                    false, false, false, null, null, false, false, null,
                    context, GetCurrentLanguageMode(context),
                    isPartial: true);
            }

            return this.VisitTyhpdefPartialFunctionDeclarationStatement(context.Statement);
        }

        /// <summary>
        /// Visits a name-only overlay <c>partial function</c> (attributes only; no signature).
        /// Grammar: T_TYHPDEF_PARTIAL function Identifier=tyhpdefPartialFunctionName T_SYM_SEMICOLON
        /// </summary>
        public override TyhpdefImportFunctionDeclAst VisitTyhpdefPartialFunctionDeclarationStatement(
            [NotNull] TyhpParser.TyhpdefPartialFunctionDeclarationStatementContext context)
        {
            IBase2Ast nameOrAlias;
            if (context.Identifier != null)
            {
                nameOrAlias = this.VisitTyhpdefPartialFunctionName(context.Identifier);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefPartialFunctionDeclarationStatement.Identifier");
                nameOrAlias = PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var functionDecl = TyhpdefImportFunctionDeclAst.Create(
                nameOrAlias,
                returnsRef: false,
                isAsync: false,
                isExtension: false,
                parameters: null,
                returnType: null,
                isDeprecated: false,
                isObsolete: false,
                docComment: null,
                context,
                GetCurrentLanguageMode(context),
                isPartial: true);
            this.AttachPartialFunctionAlias(nameOrAlias, context.AliasedAs, context);
            this.AttachOverlayAgainst(functionDecl, context);
            return functionDecl;
        }

        /// <summary>
        /// Visits a name-only <c>partial function</c> identifier (FQCN or semi-reserved; no generics).
        /// Optional <c>as</c> is attached by the declaration visitor, not this name rule.
        /// </summary>
        public override PhpNameAst VisitTyhpdefPartialFunctionName(
            [NotNull] TyhpParser.TyhpdefPartialFunctionNameContext context)
        {
            if (context.Identifier != null)
            {
                return this.VisitName(context.Identifier);
            }

            if (context.SemiReserved != null)
            {
                var reserved = this.VisitSemiReserved(context.SemiReserved);
                return PhpNameAst.Create(reserved.ValueString ?? "", 0, context);
            }

            this.ReportMissingRequired(context, "tyhpdefPartialFunctionName");
            return PhpNameAst.CreateError(context, GetCurrentLanguageMode(context));
        }

        /// <summary>
        /// Visits a single tyhpdef property (variable name plus optional expected default).
        /// Grammar: tyhpdefProperty
        ///   : Variable=T_VARIABLE (T_COALESCE CoalesceExpr=expr)?
        /// </summary>
        public override TyhpdefPropertyAst VisitTyhpdefProperty([NotNull] TyhpParser.TyhpdefPropertyContext context)
        {
            if (context.Variable == null)
            {
                this.ReportMissingRequired(context, "tyhpdefProperty.Variable");
                return TyhpdefPropertyAst.Create("<error>", null, context, GetCurrentLanguageMode(context));
            }

            var coalesceExpr = context.CoalesceExpr != null
                ? this.VisitExpr(context.CoalesceExpr)
                : null;

            return TyhpdefPropertyAst.Create(
                context.Variable.Text,
                coalesceExpr,
                context,
                GetCurrentLanguageMode(context)
            );
        }

        /// <summary>
        /// Visits a tyhpdef property list.
        /// Grammar: tyhpdefPropertyList
        ///   : Items+=tyhpdefProperty (T_SYM_COMMA Items+=tyhpdefProperty)*
        /// </summary>
        public override TyhpdefPropertyListAst VisitTyhpdefPropertyList([NotNull] TyhpParser.TyhpdefPropertyListContext context)
            => TyhpdefPropertyListAst.Create(
                (context._Items ?? []).Where(item => item != null).Select(this.VisitTyhpdefProperty!),
                context
            );

        /// <summary>
        /// Entry point for parsing Tyhpdef source files.
        /// Grammar: tyhpdefSrcFile
        ///   : TyhpdefBlock=tyhpdefBlock EOF   #tyhpdefFile
        /// </summary>
        public override TyhpdefSrcFileAst VisitTyhpdefFile([NotNull] TyhpParser.TyhpdefFileContext context)
        {
            // Missing/invalid open tag leaves TyhpdefBlock null after recovery — do not NRE.
            if (context.TyhpdefBlock == null)
            {
                return TyhpdefSrcFileAst.Create(this._filename, this._fileHash, null, null, null);
            }

            var block = this.VisitTyhpdefBlock(context.TyhpdefBlock);
            return TyhpdefSrcFileAst.Create(
                this._filename,
                this._fileHash,
                null,
                block != null ? [block] : null,
                null
            );
        }

        /// <summary>
        /// Visits a tyhpdef block (tyhpdef open tag followed by statement list).
        /// Grammar: tyhpdefBlock
        ///   : T_TYHPDEF_OPEN_TAG StatementList=tyhpdefTopStatementList
        /// </summary>
        public override PhpTopStatementListAst VisitTyhpdefBlock([NotNull] TyhpParser.TyhpdefBlockContext context)
        {
            if (context.StatementList == null)
            {
                return PhpTopStatementListAst.Create(null, context, GetCurrentLanguageMode(context));
            }

            return this.VisitTyhpdefTopStatementList(context.StatementList);
        }

        /// <summary>
        /// Entry point for parsing tagless Tyhpdef source files (source.tagless enabled).
        /// Grammar: tyhpdefTaglessSrcFile
        ///   : T_TYHPDEF_OPEN_TAG? StatementList=tyhpdefTopStatementList EOF   #tyhpdefTaglessFile
        /// The open tag is optional; the whole file is a single Tyhpdef block.
        /// </summary>
        public override TyhpdefSrcFileAst VisitTyhpdefTaglessFile([NotNull] TyhpParser.TyhpdefTaglessFileContext context)
        {
            var block = context.StatementList != null
                ? this.VisitTyhpdefTopStatementList(context.StatementList)
                : PhpTopStatementListAst.Create(null, context, GetCurrentLanguageMode(context));
            return TyhpdefSrcFileAst.Create(
                this._filename,
                this._fileHash,
                null,
                block != null ? [block] : null,
                null
            );
        }

        /// <summary>
        /// Dispatches to the standalone tyhpdef extension declaration statement.
        /// Grammar: Statement=tyhpdefStandaloneExtensionDeclarationStatement   #tyhpdefStandaloneExtensionTopDecl
        /// </summary>
        public override TyhpdefStandaloneExtensionDeclAst VisitTyhpdefStandaloneExtensionTopDecl(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionTopDeclContext context)
        {
            if (context.Statement == null)
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionTopDecl.Statement");
                return TyhpdefStandaloneExtensionDeclAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            var decl = this.VisitTyhpdefStandaloneExtensionDeclarationStatement(context.Statement);
            if (context.Attributes != null)
            {
                decl.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return decl;
        }

        /// <summary>
        /// Visits a standalone tyhpdef <c>extension Name { ... }</c> declaration.
        /// Optional generic parameters and an optional header <c>extends Type</c> match live Tyhp.
        /// Grammar: tyhpdefStandaloneExtensionDeclarationStatement
        ///   : tyhpdefDeprecatedOrObsolete? T_TYHP_EXTENSION Identifier=T_STRING
        ///       GenericParameters=tyhpGenericParameterDeclarations?
        ///       (T_EXTENDS TargetType=typeExprWithoutStatic)?
        ///       FindDocComment=T_OPEN_CURLY_BRACE
        ///       StatementList=tyhpdefStandaloneExtensionMemberList
        ///       T_CLOSE_CURLY_BRACE
        /// </summary>
        public override TyhpdefStandaloneExtensionDeclAst VisitTyhpdefStandaloneExtensionDeclarationStatement(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionDeclarationStatementContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;
            var isDeprecated = deprecatedOrObsolete?.ValueInt64 == TyhpParser.T_TYHPDEF_DEPRECATED;
            var isObsolete = deprecatedOrObsolete?.ValueInt64 == TyhpParser.T_TYHPDEF_OBSOLETE;
            ReadTyhpdefDeclModifier(deprecatedOrObsolete, out isDeprecated, out isObsolete, out var isOmit);

            var docComment = context.FindDocComment != null
                ? this.FindPossibleDocComment(context.FindDocComment)
                : null;

            string name;
            if (context.Identifier != null)
            {
                name = context.Identifier.Text;
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionDeclarationStatement.Identifier");
                name = "<error>";
            }

            TyhpExtensionFunctionListAst functionList;
            if (context.StatementList != null)
            {
                functionList = this.VisitTyhpdefStandaloneExtensionMemberList(context.StatementList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionDeclarationStatement.StatementList");
                functionList = TyhpExtensionFunctionListAst.Create(null, context);
            }

            var result = TyhpdefStandaloneExtensionDeclAst.Create(
                name,
                functionList,
                isDeprecated,
                isObsolete,
                docComment,
                context,
                GetCurrentLanguageMode(context)
            );
            this.AttachExtensionBlockTarget(result, context.GenericParameters, context.TargetType);
            return result;
        }

        /// <summary>
        /// Visits the member list of a standalone tyhpdef extension body.
        /// Grammar: tyhpdefStandaloneExtensionMemberList
        ///   : Items+=tyhpdefStandaloneExtensionMember*
        /// </summary>
        public override TyhpExtensionFunctionListAst VisitTyhpdefStandaloneExtensionMemberList(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionMemberListContext context)
            => TyhpExtensionFunctionListAst.Create(
                (context._Items ?? []).Where(item => item != null)
                    .Select(this.VisitTyhpdefStandaloneExtensionMemberAsExtensionMember!),
                context
            );

        /// <summary>
        /// Dispatches tyhpdefStandaloneExtensionMember labeled alternatives (no unlabeled base
        /// rule visitor is generated since every alternative carries a label).
        /// </summary>
        private IExtensionMemberAst VisitTyhpdefStandaloneExtensionMemberAsExtensionMember(
            TyhpParser.TyhpdefStandaloneExtensionMemberContext context)
        {
            return context switch
            {
                TyhpParser.TyhpdefStandaloneExtensionFunctionMemberContext ctx =>
                    this.VisitTyhpdefStandaloneExtensionFunctionOrError(ctx.FunctionDecl, context),
                TyhpParser.TyhpdefStandaloneExtensionOperatorMemberContext ctx =>
                    this.VisitTyhpdefStandaloneExtensionOperatorOrError(ctx.OperatorDecl, context),
                TyhpParser.TyhpdefStandaloneExtensionTargetGroupMemberContext ctx =>
                    this.VisitTyhpdefStandaloneExtensionTargetGroupOrError(ctx.TargetGroup, context),
                _ => this.HandleUnexpectedAlternativeSpecial<IExtensionMemberAst>(
                    context,
                    "tyhpdefStandaloneExtensionMember",
                    () => TyhpdefInlineExtensionFunctionAst.Create(
                        PhpMethodDeclAst.CreateError(context, GetCurrentLanguageMode(context)),
                        context,
                        GetCurrentLanguageMode(context)))
            };
        }

        /// <summary>
        /// Visits a standalone tyhpdef extension function member (short <c>fn ... =&gt; ...;</c>
        /// only — <c>function</c> and brace bodies are illegal on standalone tyhpdef extensions,
        /// matching live Tyhp short syntax).
        /// Grammar: tyhpdefStandaloneExtensionFunctionDecl
        ///   : Attributes=attributes? tyhpdefDeprecatedOrObsolete? fn
        ///       GenericIdentifier=tyhpOptionalGenericIdentifierWithoutConstructor
        ///       FindDocComment=T_OPEN_ROUND_BRACE ParameterList=parameterList
        ///       T_CLOSE_ROUND_BRACE ReturnType=returnType T_DOUBLE_ARROW
        ///       Expr=expr T_SYM_SEMICOLON
        /// </summary>
        public override TyhpdefInlineExtensionFunctionAst VisitTyhpdefStandaloneExtensionFunction(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionFunctionContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var languageMode = GetCurrentLanguageMode(context);
            var docComment = this.FindPossibleDocComment(context.FindDocComment);

            PhpNameAst nameAst;
            if (context.GenericIdentifier != null)
            {
                nameAst = this.VisitTyhpOptionalGenericIdentifierWithoutConstructor(context.GenericIdentifier);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionFunctionDecl.GenericIdentifier");
                nameAst = PhpNameAst.CreateError(context, languageMode);
            }

            var genericArgs = (nameAst as TyhpGenericIdentifierAst)?.GenericArguments;

            var parameters = this.ReadExtensionCallableParameters(
                context.Parameters,
                context,
                languageMode,
                out var byRefReceiver);

            ITypeExpression? returnType = null;
            if (context.ReturnType != null)
            {
                returnType = this.VisitReturnType(context.ReturnType);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionFunctionDecl.ReturnType");
            }

            IExpression expr;
            if (context.Expr != null)
            {
                expr = this.VisitExpr(context.Expr);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionFunctionDecl.Expr");
                expr = ErrorAst.Create(context, languageMode);
            }

            var body = PhpStatementBlockAst.Create(
                [PhpUnaryOpAst.Create(
                    TokenValueAst.Create("return", TyhpParser.T_RETURN, context),
                    expr,
                    context,
                    languageMode
                )],
                context,
                languageMode
            );

            var method = PhpMethodDeclAst.Create(
                    nameAst.ValueString ?? "",
                    false,
                    null,
                    parameters,
                    returnType,
                    body,
                    docComment,
                    context,
                    languageMode,
                    isShortSyntax: true)
                .WithGrammarAddon("identifier", genericArgs);

            var result = TyhpdefInlineExtensionFunctionAst.Create(method, context, languageMode);
            if (byRefReceiver != null)
            {
                var receiverToken = TokenValueAst.Create(byRefReceiver, context, languageMode);
                result.AddGrammarAddon(TyhpExtensionDeclAst.ByRefReceiverAddonKey, receiverToken);
                method.AddGrammarAddon(TyhpExtensionDeclAst.ByRefReceiverAddonKey, receiverToken);
            }
            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                var attributes = this.VisitAttributes(context.Attributes);
                result.AddAttributes(attributes);
                method.AddAttributes(attributes);
            }

            return result;
        }

        /// <summary>
        /// Visits a standalone tyhpdef extension operator member (short <c>=&gt;</c> form only).
        /// Grammar: tyhpdefStandaloneExtensionOperatorDecl
        ///   : Attributes=attributes? tyhpdefDeprecatedOrObsolete? T_TYHP_OPERATOR
        ///       Op=tyhpClassOperatorOverloadOp T_SYM_LT
        ///       TargetType=typeExprWithoutStatic T_SYM_GT T_OPEN_ROUND_BRACE
        ///       functionParametersGrammarAddon LeftParameter=attributedParameter
        ///       (T_SYM_COMMA RightParameter=attributedParameter)? T_CLOSE_ROUND_BRACE
        ///       ConvertReturnType=returnType T_DOUBLE_ARROW Expr=expr
        ///       T_SYM_SEMICOLON
        /// </summary>
        public override TyhpOperatorOverloadAst VisitTyhpdefStandaloneExtensionOperator(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionOperatorContext context)
        {
            var deprecatedOrObsolete = context.tyhpdefDeprecatedOrObsolete() != null
                ? this.VisitTyhpdefDeprecatedOrObsolete(context.tyhpdefDeprecatedOrObsolete())
                : null;

            var languageMode = GetCurrentLanguageMode(context);

            TokenValueAst op;
            if (context.Op != null)
            {
                op = this.VisitTyhpClassOperatorOverloadOp(context.Op);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionOperatorDecl.Op");
                op = TokenValueAst.CreateError(context, languageMode);
            }

            this.ReportLegacyOperatorTarget(context.LegacyTarget, context);

            PhpParameterAst leftParam;
            if (context.LeftParameter != null)
            {
                leftParam = this.VisitAttributedParameter(context.LeftParameter);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionOperatorDecl.LeftParameter");
                leftParam = this.CreateErrorParameter(context, languageMode);
            }

            var rightParam = context.RightParameter != null
                ? this.VisitAttributedParameter(context.RightParameter)
                : null;

            ITypeExpression? returnType = null;
            if (context.ConvertReturnType != null)
            {
                returnType = this.VisitReturnType(context.ConvertReturnType);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionOperatorDecl.ConvertReturnType");
            }

            PhpStatementBlockAst? body = null;
            if (context.Expr != null)
            {
                var expr = this.VisitExpr(context.Expr);
                body = PhpStatementBlockAst.Create(
                    [PhpUnaryOpAst.Create(
                        TokenValueAst.Create("return", TyhpParser.T_RETURN, context),
                        expr,
                        context,
                        languageMode
                    )],
                    context,
                    languageMode
                );
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionOperatorDecl.Expr");
            }

            var result = TyhpOperatorOverloadAst.Create(
                op,
                leftParam,
                rightParam,
                returnType,
                body,
                null,
                context,
                languageMode,
                isShortSyntax: true);

            if (deprecatedOrObsolete != null)
            {
                result.AddGrammarAddon("deprecatedOrObsolete", deprecatedOrObsolete);
            }

            if (context.Attributes != null)
            {
                result.AddAttributes(this.VisitAttributes(context.Attributes));
            }

            return result;
        }

        public override TyhpExtensionDeclAst VisitTyhpdefStandaloneExtensionTargetGroup(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionTargetGroupContext context)
        {
            TyhpExtensionFunctionListAst functionList;
            if (context.StatementList != null)
            {
                functionList = this.VisitTyhpdefStandaloneExtensionGroupMemberList(context.StatementList);
            }
            else
            {
                this.ReportMissingRequired(context, "tyhpdefStandaloneExtensionTargetGroup.StatementList");
                functionList = TyhpExtensionFunctionListAst.Create(null, context);
            }

            return this.CreateExtensionTargetGroup(
                context,
                context.GenericParameters,
                context.TargetType,
                context.FindDocComment,
                functionList);
        }

        public override TyhpExtensionFunctionListAst VisitTyhpdefStandaloneExtensionGroupMemberList(
            [NotNull] TyhpParser.TyhpdefStandaloneExtensionGroupMemberListContext context)
            => TyhpExtensionFunctionListAst.Create(
                (context.tyhpdefStandaloneExtensionGroupMember() ?? [])
                    .Select(this.VisitTyhpdefStandaloneExtensionGroupMemberAsExtensionMember),
                context);

        private IExtensionMemberAst VisitTyhpdefStandaloneExtensionFunctionOrError(
            TyhpParser.TyhpdefStandaloneExtensionFunctionContext? function,
            ParserRuleContext owner)
        {
            if (function == null)
            {
                this.ReportMissingRequired(owner, "tyhpdefStandaloneExtensionFunction");
                return TyhpdefInlineExtensionFunctionAst.Create(
                    PhpMethodDeclAst.CreateError(owner, GetCurrentLanguageMode(owner)),
                    owner,
                    GetCurrentLanguageMode(owner));
            }

            return this.VisitTyhpdefStandaloneExtensionFunction(function);
        }

        private IExtensionMemberAst VisitTyhpdefStandaloneExtensionOperatorOrError(
            TyhpParser.TyhpdefStandaloneExtensionOperatorContext? op,
            ParserRuleContext owner)
        {
            if (op == null)
            {
                this.ReportMissingRequired(owner, "tyhpdefStandaloneExtensionOperator");
                return TyhpOperatorOverloadAst.CreateError(owner, GetCurrentLanguageMode(owner));
            }

            return this.VisitTyhpdefStandaloneExtensionOperator(op);
        }

        private IExtensionMemberAst VisitTyhpdefStandaloneExtensionTargetGroupOrError(
            TyhpParser.TyhpdefStandaloneExtensionTargetGroupContext? group,
            ParserRuleContext owner)
        {
            if (group == null)
            {
                this.ReportMissingRequired(owner, "tyhpdefStandaloneExtensionTargetGroup");
                return TyhpExtensionDeclAst.CreateError(owner, GetCurrentLanguageMode(owner));
            }

            return this.VisitTyhpdefStandaloneExtensionTargetGroup(group);
        }

        private IExtensionMemberAst VisitTyhpdefStandaloneExtensionGroupMemberAsExtensionMember(
            TyhpParser.TyhpdefStandaloneExtensionGroupMemberContext context)
        {
            return context switch
            {
                TyhpParser.TyhpdefStandaloneExtensionGroupFunctionMemberContext ctx =>
                    this.VisitTyhpdefStandaloneExtensionFunctionOrError(ctx.FunctionDecl, context),
                TyhpParser.TyhpdefStandaloneExtensionGroupOperatorMemberContext ctx =>
                    this.VisitTyhpdefStandaloneExtensionOperatorOrError(ctx.OperatorDecl, context),
                _ => this.HandleUnexpectedAlternativeSpecial<IExtensionMemberAst>(
                    context,
                    "tyhpdefStandaloneExtensionGroupMember",
                    () => TyhpdefInlineExtensionFunctionAst.Create(
                        PhpMethodDeclAst.CreateError(context, GetCurrentLanguageMode(context)),
                        context,
                        GetCurrentLanguageMode(context)))
            };
        }

        /// <summary>
        /// Dispatches tyhpdefStatement labeled alternatives.
        /// Grammar: tyhpdefStatement
        ///   : T_SYM_SEMICOLON                            #tyhpdefEmptyStatement
        ///   | T_DECLARE ...                              #tyhpdefDeclare
        ///   | Statement=tyhpdefImportConstStatement       #tyhpdefImportConst
        ///   | Statement=tyhpdefImportVariableStatement    #tyhpdefImportVariable
        /// </summary>
        public ITopStatement VisitTyhpdefStatement(TyhpParser.TyhpdefStatementContext? context)
        {
            if (context == null)
            {
                return ErrorAst.Create(
                    "Missing tyhpdefStatement",
                    MessageCode.VisitorMissingRequiredNode,
                    0,
                    0,
                    languageMode: "tyhpdef");
            }

            return context switch
            {
                TyhpParser.TyhpdefEmptyStatementContext ctx => this.VisitTyhpdefEmptyStatement(ctx),
                TyhpParser.TyhpdefDeclareContext ctx => this.VisitTyhpdefDeclare(ctx),
                TyhpParser.TyhpdefImportConstContext ctx => this.VisitTyhpdefImportConst(ctx),
                TyhpParser.TyhpdefImportVariableContext ctx => this.VisitTyhpdefImportVariable(ctx),
                _ => HandleUnexpectedAlternative<ITopStatement>(context, "tyhpdefStatement")
            };
        }

        /// <summary>
        /// Visits a tyhpdef empty statement (bare semicolon).
        /// Grammar: T_SYM_SEMICOLON   #tyhpdefEmptyStatement
        /// </summary>
        public override PhpNopStatementAst VisitTyhpdefEmptyStatement([NotNull] TyhpParser.TyhpdefEmptyStatementContext context)
            => PhpNopStatementAst.Create(context, GetCurrentLanguageMode(context));

        /// <summary>
        /// Visits a tyhpdef declare statement.
        /// Grammar: T_DECLARE (...) Body=tyhpdefDeclareBody   #tyhpdefDeclare
        /// Body is <c>;</c>, <c>{ tyhpdefTopStatementList }</c>, or colon/enddeclare.
        /// </summary>
        public override PhpDeclareAst VisitTyhpdefDeclare([NotNull] TyhpParser.TyhpdefDeclareContext context)
        {
            var declareList = context.DeclareList != null
                ? this.VisitConstList(context.DeclareList)
                : PhpConstDeclListAst.Create(null, context);
            IStatement body = context.Body != null
                ? this.VisitTyhpdefDeclareBody(context.Body)
                : ErrorAst.Create(context, GetCurrentLanguageMode(context));
            return PhpDeclareAst.Create(declareList, body, context, GetCurrentLanguageMode(context));
        }

        public IStatement VisitTyhpdefDeclareBody(TyhpParser.TyhpdefDeclareBodyContext? context)
        {
            if (context == null)
            {
                return ErrorAst.Create(
                    "Missing tyhpdefDeclareBody",
                    MessageCode.VisitorMissingRequiredNode,
                    0,
                    0,
                    languageMode: "tyhpdef");
            }

            return context switch
            {
                TyhpParser.TyhpdefDeclareEmptyContext ctx => this.VisitTyhpdefDeclareEmpty(ctx),
                TyhpParser.TyhpdefDeclareBlockContext ctx => this.VisitTyhpdefDeclareBlock(ctx),
                TyhpParser.TyhpdefDeclareColonContext ctx => this.VisitTyhpdefDeclareColon(ctx),
                _ => HandleUnexpectedAlternative<IStatement>(context, "tyhpdefDeclareBody"),
            };
        }

        public override PhpNopStatementAst VisitTyhpdefDeclareEmpty([NotNull] TyhpParser.TyhpdefDeclareEmptyContext context)
            => PhpNopStatementAst.Create(context, GetCurrentLanguageMode(context));

        public override PhpStatementBlockAst VisitTyhpdefDeclareBlock([NotNull] TyhpParser.TyhpdefDeclareBlockContext context)
            => this.TyhpdefStatementsToBlock(
                context.StatementList != null
                    ? this.VisitTyhpdefTopStatementList(context.StatementList)
                    : null,
                context);

        public override PhpStatementBlockAst VisitTyhpdefDeclareColon([NotNull] TyhpParser.TyhpdefDeclareColonContext context)
            => this.TyhpdefStatementsToBlock(
                context.StatementList != null
                    ? this.VisitTyhpdefTopStatementList(context.StatementList)
                    : null,
                context);

        private PhpStatementBlockAst TyhpdefStatementsToBlock(
            PhpTopStatementListAst? statements,
            ParserRuleContext context)
        {
            var children = new List<IStatement>();
            if (statements != null)
            {
                foreach (var stmt in statements.GetAllNotNull())
                {
                    if (stmt is IStatement inner)
                    {
                        children.Add(inner);
                    }
                    else
                    {
                        this.ReportUnexpectedAlternative(context, stmt.GetType().Name);
                        children.Add(ErrorAst.Create(context, GetCurrentLanguageMode(context)));
                    }
                }
            }

            return PhpStatementBlockAst.Create(children, context, GetCurrentLanguageMode(context));
        }

        /// <summary>
        /// Dispatches tyhpdefTopStatement labeled alternatives.
        /// </summary>
        public ITopStatement? VisitTyhpdefTopStatement(TyhpParser.TyhpdefTopStatementContext? context)
        {
            if (context == null)
            {
                return null;
            }

            return context switch
            {
                TyhpParser.TyhpdefNotAttributedTopStatementContext ctx => this.VisitTyhpdefNotAttributedTopStatement(ctx),
                TyhpParser.TyhpdefAttributedTopStatementContext ctx => this.VisitTyhpdefAttributedTopStatement(ctx),
                TyhpParser.TyhpdefNameSpaceDeclContext ctx => this.VisitTyhpdefNameSpaceDecl(ctx),
                TyhpParser.TyhpdefNamespaceGroupDeclContext ctx => this.VisitTyhpdefNamespaceGroupDecl(ctx),
                TyhpParser.TyhpdefImportGroupDeclsContext ctx => this.VisitTyhpdefImportGroupDecls(ctx),
                TyhpParser.TyhpdefImportTypedGroupDeclsContext ctx => this.VisitTyhpdefImportTypedGroupDecls(ctx),
                TyhpParser.TyhpdefImportDeclsContext ctx => this.VisitTyhpdefImportDecls(ctx),
                TyhpParser.TyhpdefImportTypeContext ctx => this.VisitTyhpdefImportType(ctx),
                TyhpParser.TyhpdefImportExtensionContext ctx => this.VisitTyhpdefImportExtension(ctx),
                TyhpParser.TyhpdefGlobalImportExtensionContext ctx => this.VisitTyhpdefGlobalImportExtension(ctx),
                TyhpParser.TyhpdefGlobalImportGroupDeclsContext ctx => this.VisitTyhpdefGlobalImportGroupDecls(ctx),
                TyhpParser.TyhpdefGlobalImportTypedGroupDeclsContext ctx => this.VisitTyhpdefGlobalImportTypedGroupDecls(ctx),
                TyhpParser.TyhpdefGlobalImportDeclsContext ctx => this.VisitTyhpdefGlobalImportDecls(ctx),
                TyhpParser.TyhpdefGlobalImportTypeContext ctx => this.VisitTyhpdefGlobalImportType(ctx),
                TyhpParser.TyhpdefTypeAliasDeclContext ctx => this.VisitTyhpdefTypeAliasDecl(ctx),
                TyhpParser.TyhpdefStandaloneExtensionTopDeclContext ctx => this.VisitTyhpdefStandaloneExtensionTopDecl(ctx),
                _ => HandleUnexpectedAlternative<ITopStatement>(context, "tyhpdefTopStatement")
            };
        }

        /// <summary>
        /// Visits a non-attributed tyhpdef top statement (empty, declare, const, variable).
        /// Grammar: tyhpdefTopStatement
        ///   : Statement=tyhpdefStatement   #tyhpdefNotAttributedTopStatement
        /// </summary>
        public override ITopStatement VisitTyhpdefNotAttributedTopStatement([NotNull] TyhpParser.TyhpdefNotAttributedTopStatementContext context)
        {
            if (context.Statement == null)
            {
                return this.ReportMissingRequiredAsErrorAst(context, "tyhpdefNotAttributedTopStatement.Statement");
            }

            return this.VisitTyhpdefStatement(context.Statement);
        }

        /// <summary>
        /// Visits an attributed tyhpdef top statement (function, class, trait, interface, enum imports).
        /// Grammar: tyhpdefTopStatement
        ///   : Attributes=attributes? Statement=tyhpdefAttributedStatement   #tyhpdefAttributedTopStatement
        /// </summary>
        public override IAttributedStatement VisitTyhpdefAttributedTopStatement([NotNull] TyhpParser.TyhpdefAttributedTopStatementContext context)
        {
            if (context.Statement == null)
            {
                return this.ReportMissingRequiredAsErrorAst(context, "tyhpdefAttributedTopStatement.Statement");
            }

            var statement = this.VisitTyhpdefAttributedStatement(context.Statement);
            if (statement == null)
            {
                return this.ReportMissingRequiredAsErrorAst(context, "tyhpdefAttributedTopStatement.Statement");
            }

            if (context.Attributes != null)
            {
                var attributes = this.VisitAttributes(context.Attributes);
                statement.AddAttributes(attributes);
            }

            // Attributes sit on this wrapper, not on the inner function/class rule, so
            // AttachOverlayAgainst from the keyword misses `// @overlay-against:` written
            // before `#[…]`. Retry from the attribute start only when the inner visit
            // did not already pick up a stamp between the attribute and the keyword.
            if (statement is Base2Ast attributed
                && !attributed.AstGrammarAddons.ContainsKey("overlayAgainst"))
            {
                this.AttachOverlayAgainst(attributed, context);
            }

            return statement;
        }

        /// <summary>
        /// Visits a list of tyhpdef top-level statements.
        /// Grammar: tyhpdefTopStatementList
        ///   : Items+=tyhpdefTopStatement*
        /// </summary>
        public override PhpTopStatementListAst VisitTyhpdefTopStatementList([NotNull] TyhpParser.TyhpdefTopStatementListContext context)
        {
            var result = PhpTopStatementListAst.Create(null, context, GetCurrentLanguageMode(context));
            if (context._Items != null)
            {
                foreach (var item in context._Items)
                {
                    if (item == null)
                    {
                        continue;
                    }

                    var topStatement = this.VisitTyhpdefTopStatement(item);
                    if (topStatement != null)
                    {
                        result.Add(topStatement);
                    }
                }
            }
            return result;
        }

        public override TyhpTypeAliasAst VisitTyhpdefTypeAliasDecl([NotNull] TyhpParser.TyhpdefTypeAliasDeclContext context)
        {
            if (context.Statement == null)
            {
                this.ReportMissingRequired(context, "tyhpdefTypeAliasDecl.Statement");
                return TyhpTypeAliasAst.CreateError(context, GetCurrentLanguageMode(context));
            }

            return this.VisitTyhpTypeAlias(context.Statement)
                .WithAttributes(context.Attributes != null ? this.VisitAttributes(context.Attributes) : null);
        }


        /// <summary>
        /// typeNameGrammarAddon
        ///     : GenericArguments=tyhpGenericTypeArguments?
        ///         {this.isLanguageMode("tyhp")}?
        ///     ;
        /// </summary>
        public override IBase2Ast? VisitTypeNameGrammarAddon([NotNull] TyhpParser.TypeNameGrammarAddonContext context)
            => context.GenericArguments != null
                ? this.VisitTyhpGenericTypeArguments(context.GenericArguments)
                : null;

        public override ITypeExpression VisitTypeWithoutStaticGrammarAddon(
            TyhpParser.TypeWithoutStaticGrammarAddonContext? context)
        {
            // Callers should null-check the GrammarAddon child; keep a defensive guard so a stray
            // null context cannot NRE on ScalarType (same truncated-`?` recovery class).
            if (context == null)
            {
                return ErrorAst.Create(
                    "Missing type after error recovery",
                    Domain.Exceptions.MessageCode.VisitorMissingRequiredNode,
                    0,
                    0);
            }

            if (context.ScalarType != null)
            {
                return VisitTyhpScalarType(context.ScalarType);
            }

            if (context.StructShape != null)
            {
                return VisitTyhpStructShape(context.StructShape);
            }

            if (context.GroupedType != null)
            {
                return VisitGroupedType(context.GroupedType);
            }

            return base.VisitTypeWithoutStaticGrammarAddon(context);
        }


        /// <summary>
        /// Overrides the unprefixed use declaration grammar addon for Tyhp generics.
        ///
        /// Grammar (TyhpParser.g4):
        ///   unprefixedUseDeclarationGrammarAddon
        ///     : NamespaceName=namespaceName
        ///         (T_AS AliasedAs=T_STRING GenericArguments=tyhpGenericTypeArguments)
        ///     ;
        ///
        /// Syntax: `use Foo\Bar as Alias&lt;T, U&gt;`
        ///
        /// Creates a PhpImportDeclAst with the generic arguments attached
        /// as a grammar addon under the key "GenericArguments".
        /// </summary>
        public override PhpImportDeclAst VisitUnprefixedUseDeclarationGrammarAddon([NotNull] TyhpParser.UnprefixedUseDeclarationGrammarAddonContext context)
        {
            var namespaceName = this.VisitNamespaceName(context.NamespaceName);
            var aliasedAs = context.AliasedAs?.Text;
            var genericArguments = this.VisitTyhpGenericTypeArguments(context.GenericArguments);

            var result = PhpImportDeclAst.Create(
                null, // Use type will be set at higher level if needed
                namespaceName.ValueString,
                aliasedAs,
                context,
                GetCurrentLanguageMode(context)
            );

            result.AddGrammarAddon("GenericArguments", genericArguments);

            return result;
        }


        /// <summary>
        /// Overrides the use declaration grammar addon for Tyhp generics.
        ///
        /// Grammar (TyhpParser.g4):
        ///   useDeclarationGrammarAddon
        ///     : NamespaceName=legacyNamespaceName
        ///         (T_AS AliasedAs=T_STRING GenericArguments=tyhpGenericTypeArguments)
        ///     ;
        ///
        /// Syntax: `use \Foo\Bar as Alias&lt;T, U&gt;`
        ///
        /// Creates a PhpImportDeclAst with the generic arguments attached
        /// as a grammar addon under the key "GenericArguments".
        /// </summary>
        public override PhpImportDeclAst VisitUseDeclarationGrammarAddon([NotNull] TyhpParser.UseDeclarationGrammarAddonContext context)
        {
            var namespaceName = this.VisitLegacyNamespaceName(context.NamespaceName);
            var aliasedAs = context.AliasedAs?.Text;
            var genericArguments = this.VisitTyhpGenericTypeArguments(context.GenericArguments);

            var result = PhpImportDeclAst.Create(
                null, // Use type will be set at higher level if needed
                namespaceName.ValueString,
                aliasedAs,
                context,
                GetCurrentLanguageMode(context)
            );

            result.AddGrammarAddon("GenericArguments", genericArguments);

            return result;
        }
    }
}
